export default [{"id":5,"question":"أنا رجلٌ قد ثقل الرانُ على قلبي حتى أصبحتُ في دوَّامةٍ من المعاصي، وكم حاولتُ أن أتوب توبةً نصوحًا ولكن دون جدوى، فأصبحتُ ضعيفَ الإرادة، وفي حياتي ضَنْكٌ، علمًا بأنني مُحافظٌ على الصَّلوات الخمس، ولكن دون خشوعٍ، فكيف تُرشدونني جزاكم الله خيرًا للخروج من هذا الظلام؟","title":"ما النصيحة لمن يريد التوبة من المعاصي؟","answer":"الجواب:\nعليك يا أخي ألا تيأس، وعليك أن تحاول دائمًا التوبة والرجوع إلى الله والاستقامة على الحقِّ وترك ما حرَّم الله عليك، عليك بهذا دائمًا دائمًا دائمًا، فكل مَن تاب إلى الله -ولو رجع ألف مرةٍ- تاب الله عليه، فعليك بالصدق، وأبشر بالخير، يقول الله : قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ لَا تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا إِنَّهُ هُوَ الْغَفُورُ الرَّحِيمُ [الزمر:53] .\n\nقال العلماء: إنَّ هذه الآية في التَّائبين، أجمع العلماءُ على أنها في التَّائبين، فلا تيأس يا أخي، واحمدِ الله الذي جعلك تتألم لهذا الأمر، وتحسّ بالخطر، هذه من نِعَم الله عليك، فبعض الناس لا يحسّ بالخطر، يعمل المعاصي ولا يحسّ بالخطر، وهذه مصيبةٌ عظيمةٌ -والعياذ بالله- كون الإنسان يموت ولا يحسّ بالموت، يُبتلى بالشرور ولا يحسّ؛ هذه بليةٌ ومصيبةٌ كبرى، لكن مَن أحسَّ بالخطر وعالج الخطر وتاب إلى الله وأناب إليه فهو على خيرٍ عظيمٍ.\n\nفعليك بالمُعالجة والمُجاهدة وسؤال الله التَّوفيق والهداية والإكثار من قراءة القرآن، فالقرآن سبب كل خيرٍ، فعليك بالإكثار من قراءته وتدبُّر معانيه، يقول الله فيه: كِتَابٌ أَنْزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُولُو الْأَلْبَابِ [ص:29]، ويقول سبحانه: قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ [فصلت:44]، ويقول سبحانه: إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9]، فعليك بكتاب الله، علينا جميعًا بكتاب الله: تدبُّرًا، وتعقُّلًا، وعملًا، والله يهدي مَن يشاء .\n\nالمُصيبة الغفلة، لكن مع التَّذكر، ومع الانتباه، ومع اليقظة، ومع الإحساس بالخطر؛ فالإنسان على رجاء الخير، وعلى سبيل نجاةٍ، فليُشمر، وليصدُق مع الله، وليُبادر بالتوبة، وليحذر أن يهجم عليه الأجلُ وهو على حالات سيئةٍ، فالأجل قد يأتي بغتةً: انقلاب سيارةٍ، باصطدام، وغير هذا.\nفاتَّقِ الله يا عبدالله، وأعدّ العُدَّة، وبادر بالتوبة، واستقم على التوبة لعلك تنجو.","link":"https://binbaz.org.sa/fatwas/2750/ما-النصيحة-لمن-يريد-التوبة-من-المعاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0255.mp3","categories":["الرقائق","الطمأنينة والخشوع"]},{"id":28,"question":"هذا سائل يقول: وبعد، إلى فضيلة الشيخ عبد العزيز أطال الله في عمره رب العالمين، وجعله سبحانه ذخرًا لهذه الأمة آمين لدي يا فضيلة الشيخ ثلاث مسائل أود الإجابة عليها.الأولى: أنني يا فضيلة الشيخ إنسان مؤمن بالرب، والحمد على ذلك، والصلاة أقوم بها، والصوم كذلك، والعمرة فقد اعتمرت حتى الآن ثلاثة عشر مرة، وعمري تسعة عشر سنة، ومنذ حوالي ست سنوات مضت أقوم بشيء لا يرضاه الرب، ولا رسوله، وهو - والعياذ بالله - اللوط، والعادة السرية، ففي عامنا الفائت، وفي إجازة الربيع (1404هـ) ذهبنا إلى مكة لأخذ عمرة فصممتُ التوبة لله عن هاتين العادتين السيئتين، فتبتُ، ولله الحمد على ذلك، فلما أتى رمضان في نفس العام، أخذتُ عمرةً أيضًا، والمشكلة حينما انتهى رمضان عدتُ للعادة السرية فقط، ولم أرجع للّواط، وحينما دخل عامنا (1405هـ)، وبدأت اختبارات نصف السنة التي قد مضت منذ ما يقرب الشهرين عُدت - والعياذ بالله - إلى عادة اللوط، وتركتُها، وأود من فضيلتكم الإفتاء في ذلك، وإفادتي أفادكم الله، حتى أتوب إلى الله توبة نصوحًا، وكيف الطريق إلى ذلك؟","title":"ما كيفية التوبة من اللواط والعادة السرية؟","answer":"الجواب: الله جلَّ وعَلا حرَّم علينا الفواحش ما ظهر منها وما بطن، وأوجب علينا التوبة النصوح من جميع الذنوب، فقال : وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31]، وقال سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا تُوبُوا إِلَى اللَّهِ تَوْبَةً نَصُوحًا [التحريم:8]، وقال سبحانه: أفَلا يَتُوبُونَ إِلَى اللَّهِ ويَسْتَغْفِرُونَهُ واللَّهُ غَفُورٌ رَحِيمٌ [المائدة:74] هذه الآيات، وما جاء في معناها كلها تدل على وجوب التوبة، وأنه  قد فتح أبوابها، ويسّرها لعباده، فعليك أيها السائل أن تتقي الله، وأن تجزم بالتوبة، وتصدق بالتوبة، وأن تبتعد عن نقضها، وأن تحذر مكائد الشيطان، فإن الشيطان عدو مبين، وله نُوّاب من الإنس يدعون إلى الفواحش والمنكرات ويحبّبونها، ويحبّبون نقض التوبة، ويقولون: إن الله غفور رحيم، إن الله تواب حكيم، إن الله كذا، إن الله كذا، حتى يوقعوك فيما حرم الله، وقد ينزل بك الأجل، وأنت على معاصي الله ، فيُحال بينك وبين التوبة، ولا حول ولا قوة إلا بالله.\nفالواجب عليك أن تجزم على التوبة، وتصدق في التوبة من اللواط، ومن العادة السرية، هذان محرمان، واللواط أعظم وأشنع؛ لأن اللواط من كبائر الذنوب، ومن أعظم الجرائم، جاء في الحديث: لعن الله من عمل عمل قوم لوط، لعن الله من عمل عمل قوم لوط، لعن الله من عمل عمل قوم لوط، وقال الله في كتابه العظيم عن اللوطية: إنَّكُمْ لَتَأْتُونَ الْفَاحِشَةَ مَا سَبَقَكُمْ بِهَا مِنْ أَحَدٍ مِنَ الْعَالَمِينَ [العنكبوت:28] فأخبر أن اللوطية ما سبقهم أحد، قوم لوط، ما سبقهم أحد إلى هذه الفاحشة ممن قبلهم، نسأل الله العافية، وفي الحديث: من وجدتموه يعمل عمل قوم لوط، فاقتلوا الفاعل والمفعول به، وقد أجمع علماء الصحابة  على أن اللائط والملوط به يُقتلان إذا كانا مكلَّفَين؛ لأنها جريمة أشنع من جريمة الزنا، والعياذ بالله.\nفيجب الحذر، والتوبة الصادقة، والبُعد عن أسباب ذلك، وعن مخالطة من يدعو إلى ذلك، أو يجر إلى ذلك، أو تتوق النفس إلى فعل ذلك معه، يجب الحذر من أولئك، فإن صحبة الأشرار من أعظم أسباب الشر، ومن أعظم دواعي الشر؛ فيجب البُعد عن صحبة الأشرار، ويجب الحرص على صحبة الأخيار، مع سؤال الله الثبات، والتوفيق للاستقامة على التوبة، وعدم نقضها.\nوهكذا العادة السرية عادة قبيحة ومنكَرة، قال الله فيها وما في معناها: وَالَّذِينَ هُمْ لِفُرُوجِهِمْ حَافِظُونَ  ۝  إِلَّا عَلَى أَزْوَاجِهِمْ أو مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ  ۝  فَمَنِ ابْتَغَى ورَاءَ ذَلِكَ فَأُولَئِكَ هُمُ الْعَادُونَ [المؤمنون:5-7] أي: الظالمون، والعادة السرية غير الزوجة، وغير ملك اليمين، فتكون من العدوان والظلم، وفيها مضار كثيرة كما بيَّن أهل العلم، وبيَّن أهل الطب.\nفيجب عليك الحذر منها؛ لأنها عادة سيئة منكَرة، فإياك وإياها، واحذرها، واحذر من يشير بها، أو يدعو إليها.\nنسأل الله لنا ولك الهداية والثبات على الحق والصدق في التوبة.","link":"https://binbaz.org.sa/fatwas/2808/ما-كيفية-التوبة-من-اللواط-والعادة-السرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0001.mp3","categories":["الرقائق","الطمأنينة والخشوع"]},{"id":37,"question":"هنالك البعض يشتكون من عدم الخشوع في الصلاة، فما هو العمل الذي يجعل المرء يخشع في صلاته؟ وهل البكاء في الصلاة من ضمن ذكر الله في الخلوة؟","title":"ما العمل الذي يجعل المرء يخشع في صلاته؟","answer":"الجواب: الواجب على المؤمن أن يطمئن في صلاته، وألا ينقرها، قال الله تعالى: قَدْ أَفْلَحَ الْمُؤْمِنُونَ  ۝  الَّذِينَ هُمْ فِي صَلاتِهِمْ خَاشِعُونَ [المؤمنون:1-2].\nقال عبد الله بن أبي عامر.. دخل على النبي ﷺ وهو يصلي قال: رأيته يصلي، وله أزيزٌ كأزيز المرجل من البكاء، عليه الصلاة والسلام.\nوكان الصدِّيق  إذا صلى بالناس لا يُسمعهم من بكائه .\nوالمقصود أن البكاء من خشية الله أمر مطلوب في الصلاة وغيرها، ولا يضر الصلاة، وإذا أحس المؤمن من نفسه عدم خشوع فلينظر، فإن هذا نتج عن إعراض وعن غفلة حين الصلاة، فإذا دخل في الصف فليقبل عليها بقلبه، وليعلم أنه بين يدي الله، وأنه واقف بين يديه  يرجو رحمته ويخشى عذابه، وليتفكر، وليتدبر كتاب الله، ولينظر فيمن هو واقف بين يديه، وهو الله ، حتى يخشع في ركوعه وسجوده وقراءته وغير ذلك، وليحذر الغفلة والهواجس التي تعرض له في بيته وفي شئونه وشئون أولاده، وشئون دكانه، وشئون مزرعته، لا، وليُقبل على صلاته، وليقطع هذه الوساوس وليبتعد عنها، وليجتهد غاية الاجتهاد في الإقبال على صلاته واستحضار عظمة الله ، وأنه قائم بين يديه، وأن هذه الصلاة عبادة عظيمة مفروضة عليه؛ حتى يقبل فيها بقلبه، وحتى يخشع فيها لربه، فهذه من الأسباب التي تباعده عن الأفكار الفاسدة، وعن الغفلة في صلاته، والله المستعان.","link":"https://binbaz.org.sa/fatwas/2817/ما-العمل-الذي-يجعل-المرء-يخشع-في-صلاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0010.mp3","categories":["الطمأنينة والخشوع"]},{"id":2256,"question":"النظر إلى مكان السجود في الصلاة هل فيه حديثٌ صحيحٌ؟","title":"ما دليل النظر إلى مكان السجود في الصلاة؟","answer":"الجواب:\nما أتذكر إلا النَّهي عن رفع الأبصار، فقد ورد التَّحذير من رفع الأبصار.\nس: فما السُّنة؟\nج: الواجب طرح البصر؛ فالوعيد على رفع الأبصار إلى السماء يُفيد أن الواجب طرحها.\nس: النظر إلى الأمام؟\nج: السنة إلى موضع السّجود؛ لأنه أقرب إلى الخشوع.\nس: عند الإيماء وعند التَّشهد هل ورد شيءٌ يُحدد مكان البصر؟\nج: ما أذكر شيئًا في هذا، والمقصود أن يتعاطى ما هو أقرب إلى الخشوع.","link":"https://binbaz.org.sa/fatwas/22379/ما-دليل-النظر-الى-مكان-السجود-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل على النظر إلى مكان السجود في الصلاة دليل.mp3","categories":["الطمأنينة والخشوع"]},{"id":2314,"question":"ما الضَّابط بين صلاة النَّقارين وصلاة المُطَوِّلين في الصلاة؟","title":"ما الضَّابط بين نَقْر الصلاة وتطويلها الزائد؟","answer":"الجواب:\nالنَّقار الذي ما يُتم ركوعه ولا يطمئنّ، فالنَّقر: عدم الطُّمأنينة؛ كونه يركع ويسجد بعجلةٍ.  والإطالة: هي التي تشقّ على الناس، فيُطوّل كثيرًا حتى يشقَّ على الناس، لا، أمَّا إذا كان وحده فلا بأس.\nس: الأصل في التَّراويح؟\nج: الوسط، لا ينقر، ولا يُطوّل على الناس، وسط؛ يطمئن ولا يُطوّل على الناس.","link":"https://binbaz.org.sa/fatwas/22438/ما-الضابط-بين-نقر-الصلاة-وتطويلها-الزاىد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الضَّابط بين صلاة النَّقارين وصلاة المُطَوِّلين في الصلاة.mp3","categories":["الطمأنينة والخشوع"]},{"id":3568,"question":"الخشوع أليس خشوع القلب؟","title":"هل الخشوع يكون في القلب والجوارح؟","answer":"الجواب: والجوارح أيضاً: قَدْ أَفْلَحَ الْمُؤْمِنُونَ  ۝  الَّذِينَ هُمْ فِي صَلَاتِهِمْ خَاشِعُونَ [المؤمنون: 1 - 2] الأهم خشوع القلب، وإذا خشع القلب خشعت الجوارح، والطمأنينة ركن من أركان الصلاة لا بدّ منها.","link":"https://binbaz.org.sa/fatwas/23750/هل-الخشوع-يكون-في-القلب-والجوارح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الخشوع خشوع القلب والجوارح.mp3","categories":["الطمأنينة والخشوع"]},{"id":3592,"question":"الحد الأدنى من الطمأنينة قدر تسبيحة في الركوع والسجود؟","title":"ما الحد الأدنى للطمأنينة في الصلاة؟","answer":"الجواب: إذا اطمأن وأتى بتسبيحة أجزأ، والسنة ثلاث فأكثر، والواجب مرة.....\nالطمأنينة ركن لا بدّ منه، والتسبيحة واجبة.","link":"https://binbaz.org.sa/fatwas/23774/ما-الحد-الادنى-للطمانينة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الطمأنينة في الصلاة.mp3","categories":["الطمأنينة والخشوع"]},{"id":3742,"question":"حمل النبي ﷺ لإمامة: هل ينافي ذلك الخشوع؟","title":"هل حمل الطفل في الصلاة ينافي الخشوع؟","answer":"الجواب: لا ما ينافي الخشوع، إذا كان يستطيع ولا يتكلف، ثم هو للدلالة والتعليم؛ ليعلم الناس هذا الأمر، مثل ما صلى على المنبر ونزل ليعلم الناس أن مثل هذه الأمور لا تخل بالصلاة.\nس: ما ورد أن قول ثلاث حركات تبطل الصلاة...؟\nالشيخ: لا... ، هذا كلام بعض الرواة ما له حد محدود، لكن ينبغي فيها الخشوع وعدم العبث، وحمل الجارية أو وضعها ليس عملًا متواليًا، هذا لمصلحة الصلاة للبيان والتعليم.","link":"https://binbaz.org.sa/fatwas/23934/هل-حمل-الطفل-في-الصلاة-ينافي-الخشوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حمل النبي لإمامة، هل ينافي الخشوع.mp3","categories":["الطمأنينة والخشوع"]},{"id":5091,"question":"سائل يقول: سماحة الشيخ جزاه الله كل خيرًا.هنالك البعض يشتكون من عدم الخشوع في الصلاة، فما هو العمل الذي يجعل المرء يخشع في صلاته؟ وهل البكاء في الصلاة من ضمن ذكر الله في الخلوة؟","title":"ما السبيل إلى الخشوع في الصلاة؟","answer":"الجواب: الواجب على المؤمن أن يطمئن في صلاته، وألا ينقرها، قال الله تعالى: قَدْ أَفْلَحَ الْمُؤْمِنُونَ  ۝  الَّذِينَ هُمْ فِي صَلاتِهِمْ خَاشِعُونَ [المؤمنون:1-2]. قال عبدالله بن أبي عامر.. دخل على النبي ﷺ وهو يصلي قال: \"رأيته يصلي، وله أزيزٌ كأزيز المرجل من البكاء\" عليه الصلاة والسلام. وكان الصدِّيق  إذا صلى بالناس لا يُسمعهم من بكائه رضي الله عنه. والمقصود أن البكاء من خشية الله أمر مطلوب في الصلاة وغيرها، ولا يضر الصلاة، وإذا أحس المؤمن من نفسه عدم خشوع فلينظر: فإن هذا نتج عن إعراض وعن غفلة حين الصلاة، فإذا دخل في الصف فليقبل عليها بقلبه، وليعلم أنه بين يدي الله، وأنه واقف بين يديه  يرجو رحمته ويخشى عذابه، وليتفكر، وليتدبر كتاب الله، ولينظر فيمن هو واقف بين يديه، وهو الله ، حتى يخشع في ركوعه وسجوده وقراءته وغير ذلك، وليحذر الغفلة والهواجس التي تعرض له في بيته وفي شئونه وشئون أولاده، وشئون دكانه، وشئون مزرعته، لا، وليُقبل على صلاته، وليقطع هذه الوساوس وليبتعد عنها، وليجتهد غاية الاجتهاد في الإقبال على صلاته واستحضار عظمة الله ، وأنه قائم بين يديه، وأن هذه الصلاة عبادة عظيمة مفروضة عليه، حتى يقبل فيها بقلبه، وحتى يخشع فيها لربه، فهذه من الأسباب التي تباعده عن الأفكار الفاسدة، وعن الغفلة في صلاته. والله المستعان.","link":"https://binbaz.org.sa/fatwas/29994/ما-السبيل-الى-الخشوع-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 10.mp3","categories":["الطمأنينة والخشوع"]},{"id":5960,"question":"تغميض العينين في الصلاة يقال: مكروه، فهل على ذلك دليل؟ مع العلم ابن القيم يقول: لا بأس به إذا كان يدعو إلى الخشوع في الصلاة؟","title":"بيان كراهة تغميض العينين في الصلاة","answer":"الجواب: لا أعلم فيه شيئًا إلا أنه يذكر من فعل اليهود في صلاتهم، ولا أعرف في ذلك حجة، واضحة إلا أنه مشهور عن كثير من الفقهاء أنه من فعل اليهود في صلاتهم؛ ولأنه لم ينقل، فالأولى عدم التغميض؛ لأن العبادات توقيفية، فالذي لم ينقل تركه أولى، فتكون عينه على عادتها، أما كونها يتعمد التغميض؛ فالأولى ترك ذلك. السؤال: لكن أمامه مناظر يخشى أن يفتن بها وغمض هروبًا منها؟ الجواب: يغض بصره ، يطرح بصره إلى موضع سجوده، ولا حاجة للتغميض.","link":"https://binbaz.org.sa/fatwas/1321/بيان-كراهة-تغميض-العينين-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_290.mp3","categories":["الطمأنينة والخشوع","مكروهات الصلاة"]},{"id":6294,"question":"كثير من الأئمة - هداهم الله- يكون زمن تأديتهم للصلاة على النصف من صلاتنا هنا في المسجد التي صليناها مع سماحتكم؛ لهذا لا يمكنون المأمومين من الطمأنينة، والخشوع الذي هو لب الصلاة، فهل تتكرمون بالتعميم عليهم، ومناصحتهم؟","title":"أهمية الطمأنينة في الصلاة والمحافظة على خشوعها","answer":"الجواب:  إن شاء الله، هذا لا شك طيب، ولا شك أن هذا واقع، كثير من الأئمة عنده عجلة في ركوعه، ولا سجوده، ولا ينبغي، ينبغي له أن يطمئن عند سجوده، وركوعه حتى يطمئن الناس، وحتى يتلاحق الكبير، والضعيف، والمريض في ركوعه، وسجوده. ومما ينبغي أن يفعل كونه يسبح ثلاث مرات، أو خمس مرات، سبحان ربي العظيم في الركوع ثلاث مرات، أو خمسًا، أو سبعًا، ويقول: سبحان ربي الأعلى في السجود كذلك، ويقول مع هذا: سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي، ويدعو في سجوده ما تيسر؛ حتى يشابه فعل النبي ﷺ. وجاء عن أنس أنه رأى إمامًا مطمئنًا في صلاته، يعد له عشر تسبيحات، فقال: إن هذا أشبه الناس بصلاة النبي، عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/1801/اهمية-الطمانينة-في-الصلاة-والمحافظة-على-خشوعها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_642.mp3","categories":["الطمأنينة والخشوع"]},{"id":6594,"question":"من المعلوم أن الخشوع في الصلاة، وحضور القلب من شروط صحتها، فلا أحقق ذلك إلا بإغماض عيني؛ لأنني أنشغل كثيرًا بما يطبع على السجاد الذي نصلي فيه من زخارف، وكتابة، مثل كلمة .. لأن تخصصي بالخط العربي، والزخرفة الإسلامية؛ لذا أجد الشيطان يصرفني للتفكير فيها حتى في موضوع السجود، فهل ينقص إغماض عيني، هذا من صلاتي أفيدونا جزاكم الله خيرًا؟","title":"حكم إغماض العينين في الصلاة للخشوع","answer":"الجواب: لا ينقص من صلاتك شيئًا، الحمد لله، السنة عدم الإغماض، وإذا أغمضتها لعلة من العلل، فلا حرج، والسنة عدم الإغماض، والخشوع من كمال الصلاة، وليس شرطًا فيها، الخشوع كونه يخشع، ولا يحضره الوساوس، هذا من كمالها، وليس شرطًا فيها، إنما الشرط الطمأنينة، هذا ركن كونه يطمئن حتى يرجع كل فقار إلى مكانه في ركوعه، في سجوده، وبين السجدتين، واعتداله بعد الركوع هذا كونه يطمئن، هذا ركن، أما كونه يترك الخشوع ما يوسوس، ولا شيء هذا كمال، هذا من الكمال.","link":"https://binbaz.org.sa/fatwas/2437/حكم-اغماض-العينين-في-الصلاة-للخشوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_964.mp3","categories":["الطمأنينة والخشوع"]},{"id":6750,"question":"إذا صلى المصلي الصلاة بدون خشوع، وجاء بالأركان، والواجبات، والسنن، فهل الصلاة مقبولة؟","title":"حكم الإتيان بالصلاة دون خشوع","answer":"الجواب: صحيحة لكن ناقصة، وليس له منها إلا ما عقل منها، أو خشع فيها، لكنها صحيحة إذا كان ما نقرها، إذا كان ما اطمئن، بل نقرها ما تصح تكون باطلة، أما إذا اطمئن فيها، ولكن عنده وساوس، عنده أوهام، عنده شيء من التفكير، صلاته صحيحة وناقصة.","link":"https://binbaz.org.sa/fatwas/2628/حكم-الاتيان-بالصلاة-دون-خشوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1124.mp3","categories":["الطمأنينة والخشوع","مكروهات الصلاة"]},{"id":6761,"question":"إذا صلى المصلي الصلاة بدون خشوع، وجاء بالأركان، والواجبات، والسنن، فهل الصلاة مقبولة؟","title":"حكم الإتيان بالصلاة دون خشوع","answer":"الجواب: صحيحة لكن ناقصة، وليس له منها إلا ما عقل منها، أو خشع فيها، لكنها صحيحة إذا كان ما نقرها، إذا كان ما اطمئن، بل نقرها ما تصح تكون باطلة، أما إذا اطمئن فيها، ولكن عنده وساوس، عنده أوهام، عنده شيء من التفكير، صلاته صحيحة وناقصة.","link":"https://binbaz.org.sa/fatwas/2628/حكم-الاتيان-بالصلاة-دون-خشوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1124.mp3","categories":["الطمأنينة والخشوع","مكروهات الصلاة"]},{"id":7020,"question":"ما هو السبب في عدم الخشوع في الصلاة؟ وكيف يتخلص الإنسان من ذلك؟","title":"ما السبب في عدم الخشوع في الصلاة؟","answer":"الجواب:\n\nالله يقول -جل وعلا-: قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلَاتِهِمْ خَاشِعُونَ [المؤمنون:1، 2] والخشوع له أسباب، وعدمه له أسباب.\n\nللخشوع أسباب: وهو الخضوع بين يدي الله، وأن تتذكر أنك بين يدي الله، وأنك واقف بين يديه  كما في الحديث الصحيح، لا يمسح أحدكم الحصاة، فإنه يناجي ربه، وفي اللفظ الآخر: فإن الرحمة تواجهه.\n\nفالإنسان إذا قام في الصلاة فإنه يناجي ربه، فيتذكر هذا المقام العظيم، وأنه بين يدي الله، فليخشع لله، وليقبل على صلاته، وليتذكر عظمة الله  وأنه بين أعظم عظيم  وليقبل على صلاته، وليقبل على قراءته، وعلى سجوده، وركوعه، ويتذكر كل ما يلزم في هذا المقام، وأن غفلته عن الله تنقص صلاته، فينبغي له أن يتذكر؛ حتى تزول عنه الغفلة، وتزول عنه الوساوس، ويسأل ربه العون على هذا في سجوده، وفي آخر التحيات يقول: اللهم أعني على الخشوع، اللهم يسر الخشوع، اللهم أعذني من الشيطان، ومن شر نفسي، يسأل ربه، يستعين به .","link":"https://binbaz.org.sa/fatwas/2956/ما-السبب-في-عدم-الخشوع-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1406.mp3","categories":["الطمأنينة والخشوع","مكروهات الصلاة"]},{"id":7859,"question":"أيضاً يقول: ما حكم صلاة الإمام الذي يسرع في الصلاة بحيث لا يتمكن المأموم من قراءة الفاتحة، فهل صلاته صحيحة أم لا، وفقكم الله؟","title":"ما حكم الإسراع وعدم الطمأنينة في الصلاة؟","answer":"الجواب: الواجب على الإمام وعلى المنفرد وعلى المأموم الطمأنينة، فالطمأنينة من أركان الصلاة العظيمة، فلا يجوز لمؤمن أن يتساهل في صلاته سواء كان إماماً أو مأموماً أو منفرداً؛ لما ثبت في الصحيحين عن النبي ﷺ أنه قال للمسيء صلاته: اركع حتى تطمئن راكعاً، ثم ارفع حتى تعتدل قائماً،، ثم اسجد حتى تطمئن ساجداً، ثم ارفع حتى تطمئن جالساً، ثم اسجد حتى تطمئن ساجداً، ثم افعل ذلك في صلاتك كلها، وكان عليه الصلاة والسلام إذا ركع اطمأن حتى يعود كل فقار مكانه، وإذا رفع اعتدل واستوى حتى يعود كل فقار مكانه، وإذا سجد استوى واعتدل حتى يعود كل فقار مكانه، وإذا رفع وجلس بين السجدتين اعتدل واطمأن حتى يعود كل فقار مكانه هذا هو الواجب، فالإمام الذي يسرع في الصلاة ولا يطمئن ما تصح صلاته بل تكون باطلة، فالواجب أن ينبه فإن استقام وإلا يجب عزله ولا يصلى خلفه، لابد أن يطمئن، ويجب أيضاً أن يأتي في الركوع بالتسبيح وفي السجود، في الركوع سبحان ربي العظيم والواجب مرة، والأفضل أن يكرره ثلاثاً أو أكثر خمس أو ست أو سبع، هذا هو الأفضل، وأقل الكمال ثلاث مرات يأتي بها بالطمأنينة: سبحان ربي العظيم، سبحان ربي العظيم، سبحان ربي العظيم، وإذا زاد جعلها خمساً أو سبعاً كان أفضل، والواجب مرة، وهكذا في السجود: سبحان ربي الأعلى، سبحان ربي الأعلى، سبحان ربي الأعلى، أقل الكمال ثلاثاً والواجب مرة، وإذا زاد فجعلها خمساً أو سبعاً أو عشراً كان أفضل، ويستحب أن يدعو في السجود أيضاً ويجتهد في الدعاء كما جاء في السنة عن النبي عليه الصلاة والسلام، أما الإسراع والنقر فهذا لا يجوز مطلقاً بل هو يبطل الصلاة، نسأل الله العافية. نعم.","link":"https://binbaz.org.sa/fatwas/5264/ما-حكم-الاسراع-وعدم-الطمانينة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_055/05503.mp3","categories":["صلاة الجماعة","الطمأنينة والخشوع"]},{"id":8081,"question":"ونبدأ برسالة المستمع عبد القادر السعيدي من العراق محافظة تأميم، يقول في رسالته وهو من محافظة التأميم: أثناء وقوف المصلي على سجادة الصلاة وهو استمر بالصلاة، في هذه الحالة كيف يكون اتجاه نظره، هل يجوز النظر إلى السماء أو إلى الأمام أو إلى محل سجوده؟ هذا ولكم جزيل الشكر.","title":"أين يكون موضع النظر في الصلاة؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: السنة النظر إلى محل السجود، هذا السنة، مادام قائماً يصلي فالسنة ينظر موضع سجوده، ولا ينظر لا يميناً ولا شمالاً ولا أمام ولا فوق، وقد جاءت السنة الصحيحة بالنهي عن رفع البصر إلى السماء وأن هذا على خطر أن يخطف بصره، فلا يرفع بصره إلى السماء لا في دعائه ولا في صلاته في حال الصلاة، ولكن ينظر إلى موضع سجوده. نعم. وفي الحديث الصحيح: لينتهين أقوام عن رفع أبصارهم إلى السماء في الصلاة أو لا ترجع إليهم وفي لفظ قال: أو لتخطفن أبصارهم. نعم.","link":"https://binbaz.org.sa/fatwas/5876/اين-يكون-موضع-النظر-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_085/08501.mp3","categories":["الطمأنينة والخشوع"]},{"id":8196,"question":"تقول أيضاً: هل صحيح بأن الصلاة التي ليس فيها خشوع تام لله عز وجل، لا يقبلها منا أم لا؟","title":"حكم الصلاة التي ينقصها الخشوع التام","answer":"الجواب: هذا على كل حال في خطر، والمطلوب من المصلي أن يخشع في صلاته، ويقبل عليها؛ لأن الله قال: قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلاتِهِمْ خَاشِعُونَ [المؤمنون:1-2]، فالإقبال على الصلاة والخشوع فيها من أهم المهمات، وهو روحها، فينبغي العناية بالخشوع والطمأنينة في الصلاة، في سجوده، في ركوعه، بين السجدتين، بعد الركوع حين يعتدل، يخشع ويطمئن ولا يعجل، سواء كان رجل أو امرأة جميعاً، وإذا أخل بالخشوع على وجه يكون معه النقر للصلاة وعدم الطمأنينة تبطل الصلاة، أما إذا كان يطمئن فيها، ولكن قد تعتريه بعض الهواجيس، وبعض النسيان هذا لا يبطل الصلاة، لكن ليس له من صلاته إلا ما عقل منها، وما خشع فيه وأقبل عليه، يكون له ثواب ذلك، وما فرط فيه يفوته ثوابه، فينبغي للعبد أن يقبل على الصلاة، وأن يطمئن فيها ويخشع فيها لله ، حتى يكمل ثوابه، ولكن لا تبطل إلا إذا أخل بالطمأنينة، إذا ركع ركوع ما فيه طمأنينة، يعجل ما تخشع الأعضاء، والواجب أن يطمئن حتى يرجع كل فقار إلى مكانه، حتى يتمكن من قول: (سبحان ربي العظيم) في الركوع، حتى يتمكن من قول: سبحان ربي الأعلى، حتى يتمكن من قول: (ربنا ولك الحمد) إذا اعتدل بعد الرفع من الركوع، وحتى يتمكن بين السجدتين من قول: ربي اغفر لي، يطمئن، هذا لابد منه، ولما رأى النبي ﷺ رجلاً لم يطمئن في صلاته بل ينقرها، أمره أن يعيد، فقال له: صل فإنك لم تصل، فالطمأنينة من أهم الخشوع، وهي خشوع واجب في الصلاة، في الركوع والسجود، وبين السجدتين، وحال الاعتدال من الركوع، هذا يقال لها: تسمى طمأنينة، وتسمى خشوع، لابد من هذه الطمأنينة، حتى يرجع كل فقار إلى مكانه، إذا ركع اطمأن حتى ترجع العظام إلى محالها، ويعود كل فقار إلى مكانه، وإذا رفع اطمأن وهو واقف بعد الركوع، وهكذا إذا سجد يطمئن، حتى يرجع كل فقار إلى مكانه، وهكذا بين السجدتين يطمئن ويهدأ، ولا يعجل حتى يعود كل فقار إلى مكانه. نعم.","link":"https://binbaz.org.sa/fatwas/6004/حكم-الصلاة-التي-ينقصها-الخشوع-التام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_093/09305.mp3","categories":["الطمأنينة والخشوع"]},{"id":9912,"question":"يسأل أيضاً ويقول: نحن نصلي في الصحراء ولا يتقيد الواحد منا بالنظر إلى مكان سجوده، بل يمد بصره في الصحراء، فهل هذا يبطل الصلاة؟","title":"حكم النظر في الصلاة إلى غير موضع السجود وكثرة الحركات","answer":"الجواب: مد البصر إلى جهة الأمام في الصحراء أو عن يمين أو شمال لا يبطل الصلاة، لكنه مكروه والسنة الخشوع في الصلاة والإقبال عليها وطرح البصر إلى محل السجود، كما قال الله : قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلاتِهِمْ خَاشِعُونَ [المؤمنون:1-2] وروي عن النبي ﷺ أن من الخشوع طرح البصر إلى محل السجود، وهكذا نص الأئمة والعلماء على شرعية طرح البصر إلى موضع السجود؛ لأن هذا أجمع للقلب وأبعد عن الحركة والعبث، فالسنة للمؤمن أن يطرح بصره وأن لا ينظر هاهنا وهاهنا لا في الصحراء ولا في غير الصحراء، بل يخشع في صلاته ويقبل عليها ويدع الحركات. بعض الناس قد يعبث بالساعة أو بلحيته أو بأنفه أو بشيء من ثيابه وهذا خلاف المشروع، العبث يكره إلا من حاجة إذا كان قليلاً، أما العبث الكثير المتوالي فإنه يبطل الصلاة، فينبغي للمؤمن أن يتحرى الخشوع ويحرص على الخشوع في صلاته والسكون وعدم الحركة حتى يكملها، عملاً بقوله سبحانه: قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلاتِهِمْ خَاشِعُونَ [المؤمنون:1-2] وعملاً بقول النبي ﷺ: اسكنوا في الصلاة، لما رأى ناساً يشيرون بأيديهم في الصلاة قال: اسكنوا في الصلاة فأمرهم بالسكون وهو ترك الحركة وترك العبث، وفق الله الجميع.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/8088/حكم-النظر-في-الصلاة-الى-غير-موضع-السجود-وكثرة-الحركات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_267/26704.mp3","categories":["الطمأنينة والخشوع"]},{"id":9999,"question":"تقول: إنني ولله الحمد أصلي الصلوات الخمس في أوقاتها، ولكني في أغلب الأحيان لا أشعر بخشوع وخضوع في الصلاة، فبماذا تنصحوني جزاكم الله خيراً؟","title":"نصائح للخشوع في الصلاة","answer":"الجواب: أنصحك بأن تجتهدي في طلب الخشوع، يقول الله سبحانه: قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلاتِهِمْ خَاشِعُونَ [المؤمنون:1-2] فعليك أن تجتهدي في طلب الخشوع باستحضار عظمة الله وأنك بين يديه، وأن هذه الصلاة عمود الإسلام وأن الخشوع من كمالها وتمامها، فاستحضري هذا عند دخولك في الصلاة استحضري أنك بين يدي الله بين يدي الرب العظيم الذي خلقك من العدم وغذاك بالنعم، وأوجب عليك الصلاة، استحضري هذا الرب العظيم، وأن الواجب الخضوع له وأن تؤدى هذه العبادة في غاية من الكمال والتمام الذي أمر الله به، حتى تخشعي حتى يخضع قلبك حتى يطمئن حتى يخشع لله حتى يبكي من خشيته، استحضري عظمة الله وكبرياءه وأنه ربك وإلهك وأن هذه الصلاة عمود الإسلام، وأنك كلما خشعت فيها زاد أجرك وزاد ثوابك ومتى جاهدت نفسك حصل الخير كله ولكن لا يضر الصلاة صحيحة، ولو كان فيها بعض النقص بسبب عدم الخشوع الكامل، لكن لا يضر الصلاة، الصلاة صحيحة إنما ينقص الأجر كلما زاد الخشوع زاد الأجر، وكلما ضعف الخشوع ضعف الأجر، حتى قال النبي ﷺ: إن الرجل ليقوم في الصلاة لا يكتب له إلا نصفها إلا ثلثها إلا ربعها إلا خمسها إلا سدسها إلا سبعها إلا ثمنها إلا تسعها إلا عشرها.\nبسبب الخشوع وعدمه، كلما زاد الخشوع زاد الأجر، وكلما نقص الخشوع نقص الأجر، والصلاة مجزئة وفق الله الجميع.\nالمقدم: اللهم أمين جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8162/نصاىح-للخشوع-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_300/30004.mp3","categories":["الطمأنينة والخشوع"]},{"id":10377,"question":"الأخوات حنان حسن أبو النجا مريم حسن أبو النجا من فلسطين بعثن برسالة ضمنها عددًا من الأسئلة، في أحد الأسئلة يقلن: هل يمنع فتح الراديو صحة الصلاة، خاصة وأننا لا نصغي إلى الراديو أثناء الصلاة، ولكن غالبًا ما أسمع بعض الأشياء البسيطة دون أن أنتبه لها؟","title":"فتح الراديو وقت الصلاة وتشويشه على المصلي","answer":"الجواب: لا يمنع صحة الصلاة لكن قد يشوش على المصلية والمصلي، فينبغي إغلاقه وقت الصلاة حتى لا يحصل تشويش، وإلا فلو كان مفتوحًا وهي مشغولة بصلاتها والرجل مشغول بصلاته صحت الصلاة، لكن ينبغي إغلاقه؛ لأنه قد يمر فيه أشياء تشوش على المصلي، فالمشروع للمؤمن والمؤمنة إغلاقه وقت الصلاة. نعم.","link":"https://binbaz.org.sa/fatwas/8550/فتح-الراديو-وقت-الصلاة-وتشويشه-على-المصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_339/33907.mp3","categories":["الطمأنينة والخشوع"]},{"id":10422,"question":"إحدى الأخوات المستمعات رمزت إلى اسمها بالحروف (ن. ص) تقول: كيف أعمل حتى يكون فكري محصوراً أثناء تأدية الصلاة؟","title":"الوسائل المعينة على الخشوع في الصلاة","answer":"الجواب: عليك المجاهدة، عليك أن تجاهدي نفسك حتى تجمعي قلبك وفكرك في الصلاة، إذا كان هناك شواغل تجزيها قبل الصلاة، حاجات البيت نجزيها قبل الصلاة إذا استطعت، ثم تفرغي للصلاة بقلب حاضر، أكل حاضر كلي من الأكل الحاضر، حاجة حاضرة يمكن أن تشوش عليك قدميها.. سلميها لأهلها، اقضيها حتى تأتي الصلاة وأنت في حالة الخشوع والإقبال، ولهذا قال ﷺ: لا صلاة بحضرة الطعام، ولا وهو يدافعه الأخبثان، الإنسان يلاحظ إذا كان عنده طعام يأكل حاجته، يحس ببول أو غائط يقضي حاجته، له شغل مهم يقضيه الوقت واسع بحمد الله، ثم يأتي الصلاة بقلب حاضر خاشع مقبل.\nهذا إن كانت امرأة في البيت أو مريض، أما إذا كان لا.. رجل فعليه أن يعتني بالشواغل التي عنده يعتني بها قبل الصلاة قبل الوقت، ثم يذهب إلى المسجد ويصلي مع الناس بقلب حاضر خاشع، فالصلاة عمود الإسلام أمرها عظيم، والله يقول سبحانه: قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلاتِهِمْ خَاشِعُونَ [المؤمنون:1-2]، والنبي عليه السلام يقول: جعلت قرة عيني في الصلاة.\nفالواجب على الرجل والمرأة العناية بهذا الأمر، الرجل يقضي حوائجه قبل الصلاة قبل الأذان حتى يتفرغ للصلاة فيذهب للمسجد، والمرأة كذلك تعتني إذا حضرت الصلاة فإذا هي فارغة مستعدة للصلاة بقلب خاشع، وإذا عرض عارض قدمته، مادام الوقت واسع فالحمد لله، حضر الطعام تأكل الطعام، حضر بول أو غائط تبادر تقضي حاجتها ثم تتوضأ، جاءها ضيف تسلم عليه وتقضي حاجته ثم تصلي مادام الوقت واسعاً، حتى تصلي صلاة مضبوطة قد أقبلت عليها بقلبها، وحضرت فيها بقلبها، وخشعت فيها لله، هكذا المؤمن، مع الطمأنينة وعدم العجلة وعدم النقر، الإنسان يركع ويطمئن يقول: سبحان ربي العظيم سبحان ربي العظيم سبحان ربي العظيم، سبحانك اللهم ربنا وبحمدك اللهم اغفر لي، لا يعجل، ثم يرفع ويقول: سمع الله لمن حمده، ربنا ولك الحمد إذا كان إمام أو منفرد ويطمئن حال رفعه، يعتدل يقول: ربنا ولك الحمد حمداً كثيراً طيباً مباركاً فيه ملء السماوات وملء الأرض وملء ما بينهما وملء ما شئت من شيء بعد، وهو مطمئن معتدل، واضعاً يمينه على شماله على صدره هذا السنة، وإن زاد بعد ذلك قال: أهل الثناء والمجد أحق ما قال العبد وكلنا لك عبد، اللهم لا مانع لما أعطيت ولا معطي لما منعت ولا ينفع ذا الجد منك الجد، فهذا مشروع، يفعله النبي بعض الأحيان عليه الصلاة والسلام، ثم يسجد ويطمئن في السجود يقول: سبحان ربي الأعلى سبحان ربي الأعلى سبحان ربي الأعلى ثلاث مرات أو أكثر، أدنى الكمال ثلاث وإذا زاد خمس أو سبع كان أفضل، ويدعو في سجوده ويقول: سبحانك اللهم ربنا وبحمدك اللهم اغفر لي، في الركوع والسجود، سبوح قدوس رب الملائكة والروح، سبحان ذي الجبروت والملكوت والكبرياء والعظمة، كل هذا يقال في الركوع والسجود، ولكن في السجود يدعو زيادة يقول: اللهم اغفر لي ذنبي كله دقه وجله وأوله وآخره وعلانيته وسره، اللهم أصلح قلبي وعملي، اللهم ارزقني الفقه في ديني، اللهم اغفر لي ولوالدي وللمسلمين، ونحو هذا من الدعوات في سجوده، النبي عليه السلام قال: أقرب ما يكون العبد من ربه وهو ساجد فأكثروا الدعاء، وقال عليه الصلاة والسلام: أما السجود فاجتهدوا في الدعاء فقمن أن يستجاب لكم يعني: حري أن يستجاب لكم.\nفالمقصود من هذا كله أن الإنسان يعتني بالأسباب التي تعينه على الخشوع قبل الدخول في الصلاة، حتى يحضر فيها بقلبه وحتى يطمئن ويخشع لربه؛ لأن الصلاة لها شأن عظيم، ولبها وروحها الخشوع، رزق الله الجميع التوفيق والهداية. نعم.","link":"https://binbaz.org.sa/fatwas/8603/الوساىل-المعينة-على-الخشوع-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_317/31710.mp3","categories":["الطمأنينة والخشوع"]},{"id":10446,"question":"يقول: بعض الأئمة لهم الصفات التالية: إذا قرأ أحدهم في الصلاة الجهرية فهو يطيل قراءته ويعطيها حقها فيما يجهر فيه من الصلاة، وأما باقي الصلاة أعني الجزء الذي يسر فيه، وكذلك جميع الصلوات السرية، فإذا أردت أن تعطي القراءة حقها كما وردت صفة القراءة في صفة صلاة النبي ﷺ فلا تستطيع أن تكمل الفاتحة، خاصة في الركعتين الأخيرتين؟","title":"توجيه أئمة المساجد بالطمأنينة في الصلاة وعدم العجلة","answer":"الجواب: الواجب على الأئمة أن يصلوا كما صلى النبي عليه الصلاة والسلام، يقول ﷺ: صلوا كما رأيتموني أصلي، فعليهم الطمأنينة والعناية بالقراءة وإيضاح القراءة، كما علم النبي ﷺ المسيء في صلاته، فقال له صلى الله عليه وسلم لما رآه لم يتم صلاته قال له ﷺ: إذا قمت إلى الصلاة فأسبغ الوضوء ثم استقبل القبلة وكبر، ثم اقرأ ما تيسر معك من القرآن، ثم اركع حتى تطمئن راكعاً، ثم ارفع حتى تعتدل قائماً، ثم اسجد حتى تطمئن ساجداً، ثم ارفع حتى تطمئن جالساً، ثم اسجد حتى تطمئن ساجداً، ثم افعل ذلك في صلاتك كلها.\nفالواجب على الأئمة أن يعتنوا بالصلاة، وأن يكملوها، ويوضحوا القراءة أن تكون القراءة واضحة ليس فيها نقص وليس فيها إسقاط حروف، بل يقرأ قراءة واضحة، ينتفع بها من خلفه في الجهرية، في الأولى والثانية من المغرب والعشاء وفي صلاة الفجر وفي الجمعة، يجهر جهراً ينفع المصلين ولا يعجل، والأفضل الترتيل، الأفضل أن يرتل وأن يقف على رءوس الآي كما كان النبي يفعل عليه الصلاة والسلام، حتى ينتفع المصلون بقراءته، والمأموم يستمع وينصت، إلا أنه يقرأ الفاتحة، المأموم يقرأ الفاتحة ولو كان إمامه يقرأ لم يسكت، يقرؤها ثم ينصت؛ لأنه مأمور بذلك لقوله ﷺ: لعلكم تقرءون خلف إمامكم؟ قلنا: نعم، قال: لا تفعلوا إلا بفاتحة الكتاب، فإنه لا صلاة لمن لم يقرأ بها، وهذا عام في الجهرية والسرية، لابد يقرأ المأموم، لكن لو جاء المأموم والإمام راكع أجزأه الركوع وسقطت عنه القراءة، أو نسي فلم يقرأ، أو كان جاهلاً ما يعرف الحكم الشرعي، يحسب أن المأموم ليس عليه قراءة فصلاته صحيحة، بخلاف الإمام والمنفرد فإن عليهما قراءة الفاتحة ركناً لابد منه، فلا يسقط لا جهلاً ولا سهواً، بل عليهما أن يقرأا الفاتحة، أما المأموم فأمره أوسع، يلزمه أن يقرأ فإن تركها جاهلاً أو ناسياً أو ما أدرك إلا الركوع أجزأته الركعة والحمد لله.\nوعلى الإمام أيضاً في الثالثة والرابعة من العشاء ومن الظهر والعصر والثالثة من المغرب عليه أن يطمئن أيضاً ولا يعجل حتى يقرأ المأموم الفاتحة، لا يعجل، عليه أن يقرأ قراءة مرتلة متأنية حتى يتمكن من خلفه من القراءة، لأن الناس أقسام يختلفون في سرعة القراءة وعدم سرعتها، فالإمام يراعي المأمومين ويرفق بهم ولا يعجل، وعلى المأموم أن يعتني أيضاً بالقراءة حتى يقرأ قراءة تامة متصلة حتى لا تفوته الفاتحة، بعض الناس قد يقرأ قراءة مقطعة، يقف ويسكت سكتات طويلة، هذا لا وجه له، بل يقرأ قراءة متصلة حتى يتمكن من القراءة قبل أن يركع الإمام. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8610/توجيه-اىمة-المساجد-بالطمانينة-في-الصلاة-وعدم-العجلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_318/31802.mp3","categories":["صلاة الجماعة","الطمأنينة والخشوع"]},{"id":10629,"question":"ما رأي الشرع فيمن ينشغل عن صلاته مهما حاول أن يجعلها خالصة دون تفكير؟","title":"الأمور المعينة على الخشوع في الصلاة","answer":"الجواب: عليه أن يجتهد وأن يحاسب نفسه، وأن يتقي الله في ذلك، ومتى اتقى الله أعانه الله وََمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2] فعليه أن يتقي الله وأن يحاسب نفسه ويجاهدها، حتى يجمع قلبه على الصلاة، وحتى يخلص لله في صلاته؛ وحتى يخشع فيها لربه؛ وحتى يدع الأفكار الضارة، وهذا يحتاج إلى جهود كبيرة وإلى عناية وإلى صدق وإخلاص وإقبال على الله، وسؤاله العون سبحانه وتعالى؛ حتى يجمع الله قلبه على صلاته. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8815/الامور-المعينة-على-الخشوع-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_328/32817.mp3","categories":["الطمأنينة والخشوع"]},{"id":10666,"question":"إنسان يؤدي الصلاة على الوجه المطلوب فهو يتم أركانها وواجباتها ومسنوناتها، إلا أنه يغلب عليه التفكير في أحول الدنيا ومشاغلها ومشاكلها، فهل صلاته صحيحة؟","title":"حكم التفكير في أمور الدنيا وهمومها أثناء الصلاة","answer":"الجواب: الصلاة صحيحة، لكن ينبغي له أن يجاهد نفسه، أن يجاهدها؛ حتى يجمع قلبه على صلاته؛ وحتى تنقطع عنه تلك الأفكار والهموم التي تتعلق بدنياه، فالمقام مقام مجاهدة.\nفالمؤمن يجاهد نفسه إذا دخل في الصلاة، ويحرص على جمع قلبه على الخشوع بين يدي الله وتعظيمه، وليتذكر أنه واقف بين يدي الله العظيم، حتى يخشع له سبحانه، وحتى يعظم حرمة المقام، وحتى يجمع قلبه على خوفه وخشيته وتعظيمه وتدبر ما يقرأ. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8841/حكم-التفكير-في-امور-الدنيا-وهمومها-اثناء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_329/32907.mp3","categories":["الطمأنينة والخشوع"]},{"id":10785,"question":"نبدأ أولاً برسالة المستمع المعذب الذي رجا أن لا نذكر الصريح أو الاسم الصريح واكتفى بـ (م.هـ) من خانقين بالعراق، أولاً في بداية رسالته يقول: نشكر الإذاعة أو إذاعة المملكة العربية السعودية على تقديم هذا البرنامج الديني القيم في إذاعة نداء الإسلام وإذاعة القرآن الكريم، والذي من خلاله تنشرون تعاليم الدين الإسلامي الحنيف، ونرجو من الله عز وجل أن يوفقكم في مسعاكم، ونرجو للبرنامج مزيداً من التقدم.سؤاله الأول يقول: إني سريع الصلاة، أي: إنني أقرأ سورة الفاتحة وباقي السور القصار بصورة سريعة أو حركات الصلاة سريعة، هل هذا جائز أم لا، وفقكم الله؟","title":"حكم العجلة في الصلاة ونقرها","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم على عبده ورسوله نبينا وإمامنا محمد بن عبد الله، وعلى آله وأصحابه ومن سلك سبيله واهتدى بهداه إلى يوم الدين..\nأما بعد: السنة للقاري أن يرتل قراءته وأن لا يعجل فيها؛ حتى يتدبر.. حتى يتعقل.. سواء كانت الفاتحة أو غير الفاتحة، فالسنة له التدبر والتعقل والترتيل وعدم العجلة، كما قال الله سبحانه: وَرَتِّلِ الْقُرْآنَ تَرْتِيلًا [المزمل:4]، قال : كِتَابٌ أَنزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُوْلُوا الأَلْبَابِ [ص:29]، والسرعة التي يخل بسببها بالحروف أو ببعض الآيات لا تجوز، بل يجب عليه أن يركد وأن لا يعجل حتى يقرأ قراءة سليمة واضحة يتدبرها ويتعقلها، فإذا كان يسقط بعض الحروف ويضيع بعض الحروف فهذه قراءة لا تجوز، بل يجب عليه أن يركد ويتأنى ويرتل حتى يؤدي الحروف والكلمات كاملة.\nوهكذا في الصلاة لا يعجل في الركوع ولا في السجود ولا في الجلسة بين السجدتين ولا في وقوفه بعد الركوع، بل يتأنى ويطمئن، هذا هو الواجب عليه، الطمأنينة فرض لا بد منها، والنقر للصلاة والعجلة فيها تبطلها.\nفنوصي السائل أن يطمئن في ركوعه ولا يعجل، يقول: سبحان ربي العظيم ويكررها ثلاثاً أو أكثر، ويقول: سبحانك اللهم ربنا وبحمدك اللهم اغفر لي، وإذا رفع من الركوع يطمئن وهو واقف يقول: ربنا ولك الحمد حمداً كثيراً طيباً مباركاً فيه، ملء السماوات وملء الأرض وملء ما بينهما وملء ما شئت من شيء بعد هذا هو الأفضل له.\nأما الطمأنينة فلا بد منها، لا بد أن يركد وهو قائم لا بد من الركود والاعتدال وعدم العجلة، ويقول في ذلك: «ربنا ولك الحمد» هذا واجب، هذا القول: ربنا ولك الحمد أمر واجب على الصحيح، وإذا كمل ذلك فقال: حمداً كثيراً طيباً مباركاً فيه، ملء السماوات وملء الأرض وملء ما بينهما وملء ما شئت من شيء بعد يكون هذا أكمل وأفضل.\nوقد جاء عنه ﷺ زيادة في هذا: أهل الثناء والمجد أحق ما قال العبد وكلنا لك عبد، لا مانع لما أعطيت، ولا معطي لما منعت، ولا ينفع ذا الجد منك الجد وهذا من الكمال.\nوهكذا في السجود لا يعجل، إذا سجد يسجد على الأعضاء السبعة: جبهته، وأنفه، وكفيه، وركبتيه، وأطراف قدميه، ويطمئن ولا يعجل حتى يرجع كل فقار إلى مكانه ويقول: سبحان ربي الأعلى سبحان ربي الأعلى سبحان ربي الأعلى، سبحانك اللهم ربنا وبحمدك اللهم اغفر لي ويدعو بما تيسر ولا يعجل. وكان النبي ﷺ يدعو في سجوده ويقول: اللهم اغفر لي ذنبي كله دقه وجله وأوله وآخره وعلانيته وسره فهذا دعاء مشروع، وقال عليه الصلاة والسلام: أقرب ما يكون العبد من ربه وهو ساجد فأكثروا الدعاء وقال: أما السجود فاجتهدوا في الدعاء فقمن أن يستجاب لكم.\nفينبغي للمؤمن في سجوده أن لا يعجل بل يجب عليه الطمأنينة والركود وهذا ركن من أركان الصلاة لا بد منه، ومع ذلك يشرع له أن يزيد في الطمأنينة وأن لا يعجل وأن يدعو في سجوده ويكرر سبحان ربي الأعلى والواجب مرة سبحان ربي الأعلى لكن إذا كرر ذلك ثلاثاً أو خمساً كان أفضل أو سبعاً.\nوالحاصل في هذا كله أن الواجب الطمأنينة وعدم العجلة، وبين السجدتين يطمئن أيضاً ولا يعجل ويعتدل بين السجدتين حتى يرجع كل فقار إلى مكانه ويقول: رب اغفر لي، رب اغفر لي، ربِ اغفر لي، اللهم اغفر لي وارحمني واهدني واجبرني وارزقني وعافني كل هذا جاء عن النبي ﷺ.\nوالمسلم يتأسى بنبيه ﷺ ويعمل كعمله عليه الصلاة والسلام ولا يعجل في هذه الأمور، فإن الصلاة هي عمود الإسلام، الصلاة أمرها عظيم وهي عمود الإسلام والطمأنينة فيها والركود أمر مفترض وركن من أركانها، فنوصي السائل أن يعتني بهذا الأمر وأن يخاف الله ويراقبه وأن يكمل صلاته بالطمأنينة وعدم العجلة، وهكذا قراءته يطمئن فيها ولا يعجل ويركد ويرتل حتى يقرأ قراءة واضحة يعقلها ويتدبرها ويستفيد منها. رزق الله الجميع التوفيق. نعم.","link":"https://binbaz.org.sa/fatwas/8955/حكم-العجلة-في-الصلاة-ونقرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_350/35001.mp3","categories":["الطمأنينة والخشوع"]},{"id":11080,"question":"هذا سائل رمز لاسمه بـ (ع. ع) يقول سماحة الشيخ: ما حكم قطع الصلاة والانتقال إلى مكان آخر إذا كان بجانبي إنسان كريه الرائحة، ولاسيما بأنه قد يفوتني ركن من أركان الصلاة ألا وهو: الطمأنينة؟ فنرجو من سماحة الشيخ الإجابة.","title":"حكم قطع الصلاة للابتعاد عن الرائحة الكريهة","answer":"الجواب:  لا حرج في ذلك، أقول: لا حرج في قطعها للضرورة من وجود الرائحة الكريهة .. تجعل الإنسان غير خاشع في صلاته، وغير مطمئن، فإذا قطعها ليذهب إلى جانب آخر فلا حرج في ذلك -إن شاء الله- مع العلم بأن الذي له رائحة كريهة لا يصلي مع الناس، الواجب عليه أن يصلي في بيته، إذا كان عنده الرائحة الكريهة البخر الكثير المؤذي، أو الصنان الذي في إبطه الكثير، فالواجب عليه أن يعالج هذا الشيء حتى يزول، وليس له أن يؤذي الناس، أو كان أكل ثومًا، أو بصلًا، ليس له حضور المسجد، يجب عليه أن يبتعد عن المسجد، حتى تزول تلك الرائحة الكريهة؛ لأن الرسول ﷺ: نهى من أكل ثومًا، أو بصلًا أن يقرب المسجد وكان يأمر بإخراج من فعل ذلك من المسجد، فإذا وجد فيه رائحة كريهة غير الثوم والبصل كالبخر في الفم .... الشديد الذي يؤذي من حوله له أن يفارقه يبتعد إلى جهة أخرى. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9258/حكم-قطع-الصلاة-للابتعاد-عن-الراىحة-الكريهة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_289/28906.mp3","categories":["الطمأنينة والخشوع"]},{"id":11288,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، يقول: المرسل أبو عزام من مكة المكرمة، أبو عزام له ثلاث قضايا كتب عنها بشكل مطول، لخصت ما كتبه في القضية الأولى من أنه يشكو عدم الطمأنينة في الصلاة حتى أنه يقرأ الفاتحة مكان التحيات في بعض الأحيان، فبماذا توجهونه حتى يكتسب الطمأنينة في صلاته؟ جزاكم الله خيرًا؟","title":"ما أسباب حضور القلب والطمأنينة في الصلاة؟","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه. أما بعد فإني أوصي الأخ أبا عزام بالإقبال على الله في صلاته واستحضار أنه بين يدي الله، وأن هذه الصلاة هي عمود الإسلام، وهي أعظم الفرائض بعد الشهادتين، فإذا استحضر هذا فإن الله سبحانه يعينه على الطمأنينة والخشوع وعدم النسيان، والله يقول جل وعلا: إِنْ تَتَّقُوا اللَّهَ يَجْعَلْ لَكُمْ فُرْقَانًا [الأنفال:29]، ويقول سبحانه: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، ويقول سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2]، وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4] فالوصية تقوى الله والإقبال على الصلاة وإحضار القلب بين يدي الله، والتعوذ بالله من الشيطان، وإذا غلبته الوساوس ينفث عن يساره ثلاث مرات، ويقول: أعوذ بالله من الشيطان ثلاث مرات، كما علم النبي ﷺ عثمان بن أبي العاص، ففعل ذلك فأذهب الله عنه وساوس الشيطان. المقصود أنه يتعوذ بالله من الشيطان وينفث عن يساره ثلاث مرات إذا كثرت عليه الوساوس، وأن يجمع قلبه على الله، وأنه بين يدي الله، وأنه يناجي ربه، يستحضر عظمة الله وأن الواجب خشيته وتعظيمه حتى يزول عنه هذا الهاجس الذي يشغله. نعم. المقدم: جزاكم الله خيرًا، هل يجب عليه سجود السهو إذا ما حصل له هذا الحال مرة أخرى سماحة الشيخ؟ الشيخ: لا يجب عليه سجود السهو إلا إذا سها عن واجب أو فعل محرمًا، أما مجرد الوساوس ما ترتب عليها ترك واجب ولا فعل محرم ما يضر. نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9469/ما-اسباب-حضور-القلب-والطمانينة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_376/37601.mp3","categories":["الطمأنينة والخشوع"]},{"id":11691,"question":"المستمع أحمد عبدالمعطي من مصر بعث يسأل ويقول: كيف أخشع في الصلاة؟ وما هي الأدعية التي تقال قبل الصلاة، وفي الصلاة، والتي تساعدني على الخشوع؟","title":"كيفية الخشوع في الصلاة والأسباب المعينة على ذلك","answer":"الجواب:  الخشوع في الصلاة إحضار القلب فيها بين يدي الله، والإقبال عليها، تستحضر عظمة الله، وأنك بين يديه ترجو رحمته، وتخشى عقابه، فهذا يسبب الخشوع والذل والانكسار وإحضار القلب بين يدي الله  وأن تدعو بقلب خاشع، ترجو رحمة الله، وتخشى عقابه بالدعوات الطيبة التي تستحضرها، ولو كانت غير منقولة، ولو كانت غير واردة، إذا كانت دعوات طيبة ليس فيها إثم، ولا قطيعة رحم؛ فلا بأس. اللهم اغفر لي، اللهم ارحمني، اللهم أصلح قلبي وعملي، اللهم اهدني صراطك المستقيم، اللهم أجرني من النار، اللهم اغفر لي ولوالدي إذا كان والداك مسلمين، اللهم إني أسألك الهدى والسداد، اللهم ألهمني رشدي، وأعذني من شر نفسي، هكذا في الصلاة وخارجها، حتى في خارج الصلاة، وأنت في البيت، أو تمشي، أو مضطجع، تدعو بما يسر الله من الدعوات الطيبة، المنقولة، وغير المنقولة، التي ليس فيها إثم، ولا قطيعة رحم.  يقول النبي ﷺ: ما من عبد يدعو الله بدعوة ليس فيها إثم، ولا قطيعة رحم إلا أعطاه الله بها إحدى ثلاث: إما أن تدخر له دعوته في الآخرة، وإما أن تعجل له في الدنيا، وإما أن يصرف عنه من الشر مثل ذلك قالوا: يا رسول الله! إذن نكثر؟ قال: الله أكثر. فأنت يا عبدالله! على خير في دعائك لربك، وانكسارك بين يديه، وخشوعك له في الصلاة في سجودك، أو في ركوعك، أو في بين السجدتين، أو في القيام، في جميع أجزاء الصلاة، الله يقول -جل وعلا-: قَدْ أَفْلَحَ الْمُؤْمِنُونَ [المؤمنون:1] الَّذِينَ هُمْ فِي صَلاتِهِمْ خَاشِعُونَ [المؤمنون:2] يعني: ذليلون منكسرون، قد أحضروا قلوبهم بين يدي الله، وإذا تيسر البكاء من خشية الله كان أكمل وأكمل.  ومن أعظم الأسباب في خشوعك ترك المعاصي، والحذر من المعاصي، وجهاد نفسك في تركها، والتوبة إلى الله منها. ومن أسباب الخشوع أن تدخل الصلاة وأنت فارغ القلب، ليس عندك مشاغل، وإن كنت تحس بشيء من الأذى؛ قضيت حاجتك قبل الصلاة؛ لقوله ﷺ: لا صلاة بحضرة الطعام، ولا وهو يدافعه الأخبثان فإذا .... عندك حاجة إلى البول، أو الغائط؛ بدأت بذلك طعام حاضر، بدأت بذلك، شغل شاغل أزلته، واسترحت منه؛ حتى تدخل الصلاة وأنت خاشع القلب، حاضر القلب، الفريضة والنافلة. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9882/كيفية-الخشوع-في-الصلاة-والاسباب-المعينة-على-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_391/39112.mp3","categories":["الطمأنينة والخشوع"]},{"id":11861,"question":"تقول أختنا: أثناء تأديتي للصلوات فإنني لا أؤديها بخشوع، وأنا أحس بذلك، إنني لا أؤديها بخشوع، وأيضًا فأنا أسرع، وأكثر الحركة فيها، هل علي إثم في ذلك، وهل ينقص أجري فيها، علمًا بأن ذلك خارج عن إرادتي؟","title":"من وسائل الخشوع في الصلاة","answer":"الجواب:  الواجب عليك الطمأنينة، لابد من الطمأنينة في الصلاة، أن تركعي مطمئنة، ترفعي، تعتدلي مطمئنة، تسجدي مطمئنة حتى يرجع كل فقار إلى مكانه، تجلسين بين السجدتين مطمئنة، وإذا تيسر الزيادة من الخشوع والطمأنينة وإحضار القلب والإكثار من التسبيح في السجود والركوع والدعاء في السجود كان هذا أكمل، مع الحذر من الوساوس. إذا أحسست بشيء تعوذي بالله من الشيطان الرجيم، قال الله تعالى: قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلاتِهِمْ خَاشِعُونَ [المؤمنون:1-2]، لا بد من الجهاد، والله سبحانه يقول: وَالَّذِينَ جَاهَدُوا فِينَا لَنَهْدِيَنَّهُمْ سُبُلَنَا [العنكبوت:69]، فعلى الرجل والمرأة العناية بالصلاة، والحرص على الخشوع فيها، والطمأنينة، وأداء المشروعات من الأذكار والدعاء، في الركوع يقول: (سبحان ربي العظيم سبحان ربي العظيم)، ثلاثًا، أو أكثر، والواجب مرة، ويقول: (سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي) كل هذا مشروع، وفي السجود كذلك (سبحان ربي الأعلى، سبحان ربي الأعلى) ثلاث مرات، أو أكثر، والواجب مرة، ويكثر من الدعاء في السجود، ويقول: (سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي) في السجود كالركوع، ويقول: (سبوح قدوس رب الملائكة والروح) في السجود، كما يقول في الركوع. فالمقصود: أن السنة للمؤمن أن يجتهد في أداء المشروعات مع وجوب الطمأنينة، الطمأنينة لابد منها بين الركوع والسجود، وبين السجدتين، وبعد الركوع حين يعتدل، لا بد من الطمأنينة، ومع هذا زيادة الخشوع، وزيادة التسبيح في الركوع والسجود، ويكتفى بالدعاء في السجود، كل هذا مشروع. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10054/من-وساىل-الخشوع-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_397/39717.mp3","categories":["الطمأنينة والخشوع"]},{"id":11870,"question":"تقول أختنا: أثناء تأديتي للصلوات فإنني لا أؤديها بخشوع، وأنا أحس بذلك، إنني لا أؤديها بخشوع، وأيضًا فأنا أسرع، وأكثر الحركة فيها، هل علي إثم في ذلك، وهل ينقص أجري فيها، علمًا بأن ذلك خارج عن إرادتي؟","title":"من وسائل الخشوع في الصلاة","answer":"الجواب:  الواجب عليك الطمأنينة، لابد من الطمأنينة في الصلاة، أن تركعي مطمئنة، ترفعي، تعتدلي مطمئنة، تسجدي مطمئنة حتى يرجع كل فقار إلى مكانه، تجلسين بين السجدتين مطمئنة، وإذا تيسر الزيادة من الخشوع والطمأنينة وإحضار القلب والإكثار من التسبيح في السجود والركوع والدعاء في السجود كان هذا أكمل، مع الحذر من الوساوس. إذا أحسست بشيء تعوذي بالله من الشيطان الرجيم، قال الله تعالى: قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلاتِهِمْ خَاشِعُونَ [المؤمنون:1-2]، لا بد من الجهاد، والله سبحانه يقول: وَالَّذِينَ جَاهَدُوا فِينَا لَنَهْدِيَنَّهُمْ سُبُلَنَا [العنكبوت:69]، فعلى الرجل والمرأة العناية بالصلاة، والحرص على الخشوع فيها، والطمأنينة، وأداء المشروعات من الأذكار والدعاء، في الركوع يقول: (سبحان ربي العظيم سبحان ربي العظيم)، ثلاثًا، أو أكثر، والواجب مرة، ويقول: (سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي) كل هذا مشروع، وفي السجود كذلك (سبحان ربي الأعلى، سبحان ربي الأعلى) ثلاث مرات، أو أكثر، والواجب مرة، ويكثر من الدعاء في السجود، ويقول: (سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي) في السجود كالركوع، ويقول: (سبوح قدوس رب الملائكة والروح) في السجود، كما يقول في الركوع. فالمقصود: أن السنة للمؤمن أن يجتهد في أداء المشروعات مع وجوب الطمأنينة، الطمأنينة لابد منها بين الركوع والسجود، وبين السجدتين، وبعد الركوع حين يعتدل، لا بد من الطمأنينة، ومع هذا زيادة الخشوع، وزيادة التسبيح في الركوع والسجود، ويكتفى بالدعاء في السجود، كل هذا مشروع. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10054/من-وساىل-الخشوع-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_397/39717.mp3","categories":["الطمأنينة والخشوع"]},{"id":12143,"question":"تقول: إنني في بعض الأحيان أسرع في تأدية الصلاة حفاظًا على الوضوء، فما هو توجيهكم؟","title":"حكم الإسراع في الصلاة حفاظاً على الوضوء","answer":"الجواب:  الواجب الطمأنينة من الركود في الصلاة، والخشوع، وعدم العجلة؛ حتى يرجع كل عضو إلى مكانه، كل فقار إلى مكانه، لا تعجلي، تستقيمي أولًا حتى تقرئي الفاتحة، وما تيسر معها في القيام، ثم اركعي وضعي يديك على ركبتيك، وسوي ظهرك مع رأسك، واخشعي ولا تعجلي، وقولي: سبحان ربي العظيم (سبحان ربي العظيم) (سبحان ربي العظيم) والواجب مرة، لكن تقرأها ثلاثًا، أو أكثر أفضل مع الطمأنينة، ثم ارفعي وتقولي عند الرفع: سمع الله لمن حمده ثم تقولي: ربنا ولك الحمد -أو اللهم ربنا لك الحمد،، حمدًا كثيرًا طيبًا مباركًا فيه، ملء السماوات، وملء الأرض، وملء ما بينهما، وملء ما شئت من شيء بعد هذا هو الأفضل مع الطمأنينة، وإن اقتصرت على ربنا ولك الحمد، أو اللهم ربنا لك الحمد كفى، لكن مع الطمأنينة، وعدم العجلة، لابد من الركود، وأنت واقفة حتى يرجع كل فقار إلى مكانه. لكن السنة التكبير: حمدًا كثيرًا طيبًا مباركًا فيه، ملء السماوات، وملء الأرض، وملء ما بينهما، وملء ما شئت من شيء بعده ثم تكبرين ساجدة: الله أكبر ساجدة، تسجدين على الأعضاء السبعة: على الجبهة والأنف والكفين والركبتين وأطراف القدمين، بطون قدم ...... بطون الأصابع، تخشعين في سجودك، وتطمئنين حتى يرجع كل فقار إلى مكانه بخشوع، وطمأنينة وعدم عجلة، تقولي: سبحان ربي الأعلى (سبحان ربي الأعلى) (سبحان ربي الأعلى). والأفضل ثلاثًا، وإن زدت خمسًا، أو سبعًا؛ كان أفضل، والواجب مرة مع الركود والطمأنينة وعدم العجلة. يشرع لك الدعاء في السجود، تدعين في السجود: اللهم اغفر لي اللهم اغفر لي ذنبي كله، دقه وجله، وأوله وآخره، وعلانيته وسره كان يدعو به النبي ﷺ كان النبي يدعو بهذا الدعاء -اللهم صل عليه وسلم- يقول في سجوده: اللهم اغفر لي ذنبي كله، دقه وجله، وأوله وآخره، وعلانيته وسره. وإن دعوت بغير ذلك من الدعوات الطيبة؛ كان مناسبًا، مثل: اللهم إنك عفو تحب العفو؛ فاعف عني اللهم اغفر لي ولوالدي -إذا كان والداك مسلمين- اللهم! أدخلني الجنة، اللهم أنجني من النار، اللهم اغفر لي ولوالدي؛ لقول النبي ﷺ: أما الركوع فعظموا فيه الرب، وأما السجود فاجتهدوا في الدعاء؛ فقمن أن يستجاب لكم فقمن يعني: حري أن يستجاب لكم، وقال أيضا -عليه الصلاة والسلام-: أقرب ما يكون العبد من ربه وهو ساجد؛ فأكثروا الدعاء. فالحاصل: أن عليك الطمأنينة، وعدم العجلة، عليك أن تطمئني في صلاتك، وتخشعي ولا تعجلي، فإذا نقرتيها نقرًا، ما في طمأنينة؛ بطلت، فلابد من طمأنينة حتى يرجع كل عضو إلى مكانه، كل فقار إلى مكانه، نعم.","link":"https://binbaz.org.sa/fatwas/10328/حكم-الاسراع-في-الصلاة-حفاظا-على-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_439/43912.mp3","categories":["الطمأنينة والخشوع"]},{"id":12191,"question":"يقول: إن بعضهم يتماوت في الصلاة؟","title":"إقبال الإنسان على صلاته وخشوعه فيها","answer":"الجواب:  تقدم الكلام في التماوت. المقدم: نعم. الشيخ: تقدم أنه ينبغي له أن لا يتماوت، المشروع أنه يقبل على صلاته، ويقبل عليها بقلبه، مع إقباله عليها، وخضوعه فيها لله  لا يتماوت كالنائم، بل يقبل على صلاته إقبال الحي الحاضر، القلب المنتبه لصلاته، المعظم لحرمات الله . نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10377/اقبال-الانسان-على-صلاته-وخشوعه-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_443/44318.mp3","categories":["الطمأنينة والخشوع"]},{"id":12886,"question":"مع مطلع هذه الحلقة نعود إلى رسالة المستمع: عبود أحمد بو عسكر من الجمهورية اليمنية، محافظة حضرموت، مديرية القطن، أخونا عبود عرضنا بعض أسئلته في حلقة مضت، وفي هذه الحلقة بقي له سؤال واحد يقول فيه: كنت في يوم واقفًا في مكتب أصلي الظهر، وكان أمامي في الجدار أوراق ملصقة، وبها كتابة، فنظرت إليها سهوًا، وقرأت بعض كلمات منها، فهل صلاتي مقبولة؟ أرجو الإفادة، جزاكم الله خيرًا.","title":"حكم الانشغال عن الصلاة بقراءة أوراق ملصقة على الجدران","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فالصلاة صحيحة، ولكن لا ينبغي للمصلي أن يشتغل عن الصلاة بقراءة في الجدار، أو في الأرض، بل يقبل على صلاته، ويجمع قلبه عليها، ويخشع فيها لربه -عز وجل- كما قال الله سبحانه: قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلاتِهِمْ خَاشِعُونَ [المؤمنون:1-2]. فالسنة للمصلي من رجل وامرأة، السنة له أن يقبل على صلاته، وألا ينظر في الجدران، ولا غير الجدران، بل يطرح بصره إلى موضع سجوده، ويشتغل بصلاته، ويعلم أنه يناجي ربه، وأنه واقف بين يديه  كما قال النبي ﷺ: إذا قام أحدكم في الصلاة، فإنه يناجي ربه. فعلى المؤمن أن يتقي الله في هذا، ويحرص على أن تكون صلاته في غاية من الإتقان، وأن يقبل عليها، ويخشع فيها لربه  ولا يتشاغل عنها بتفكير، أو مطالعة كتابة في جدار، أو أرض، أو غير ذلك. ثم كونك تصلي في المكتب وحدك هذا منكر، يجب عليك أن تصلي مع الجماعة في المساجد، ولا يجوز للرجل أن يصلي في مكتبه، ولا لأهل المكتب أن يصلوا في مكتبهم، بل يجب على أهل المكاتب أن يصلوا مع الناس في مساجد الله، كما قال المصطفى -عليه الصلاة والسلام-: من سمع النداء، فلم يأت؛ فلا صلاة له إلا من عذر وفي الصحيحين عن النبي ﷺ أنه هم أن يحرق على من ترك الصلاة، وصلى في بيته، قال: لقد هممت أن آمر بالصلاة فتقام، ثم آمر رجلًا فيؤم الناس، ثم أنطلق برجال معهم حزم من حطب، إلى رجال لا يشهدون الصلاة؛ فأحرق عليهم بيوتهم. ما قال: (لا يصلون) قال: «لا يشهدون» يعني: لا يشهدونها مع المسلمين في المساجد، وفي رواية لأحمد: لولا ما في البيوت من النساء والذرية؛ لحرقتها عليهم. فالواجب على كل مسلم الحذر من التخلف عن الصلاة في المساجد، والحذر من مشابهة أهل النفاق في جميع الصلوات، ولا سيما في الفجر، فإن كثيرًا من الناس قد شابه المنافقين في ذلك، فيجب الحذر، وأن تكون الصلوات الخمس كلها في المساجد، الفجر والظهر والعصر والمغرب والعشاء جميعًا، يجب على الرجل أن يصلي في المساجد مع إخوانه، ولا يجوز له أن يتخلف عنها في بيته، ولا في مكتبه، الصلاة في البيت للنساء والمرضى، أما الذي عافاه الله، الذي قد عافاه الله؛ فيلزمه أن يصلي مع إخوانه في المساجد. وقد ثبت عنه ﷺ: أنه سأله رجل أعمى، فقال: يا رسول الله! ليس لي قائد يلائمني -وفي لفظ يقودني إلى المسجد- فهل لي من رخصة أن أصلي في بيتي؟ فقال له -عليه الصلاة والسلام-: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب وفي لفظ: لا أجد لك رخصة هذا أعمى، ليس له قائد، ومع هذا يقول له النبي ﷺ: أجب، ليس لك رخصة، فكيف بحال من عافاه الله من العمى، كيف بحال القوي. الواجب على كل مسلم أن يتقي الله، وأن يحذر عقوبة الله، وأن يبادر إلى الصلاة في مساجد الله مع إخوانه، ويحظى بالأجر العظيم في ذلك، والسمعة الحسنة، والاجتماع مع إخوانه، والتعارف والتآلف، نسأل الله للجميع الهداية، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11101/حكم-الانشغال-عن-الصلاة-بقراءة-اوراق-ملصقة-على-الجدران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_467/46701.mp3","categories":["الطمأنينة والخشوع"]},{"id":13491,"question":"بعد ذلك ننتقل إلى رسالة بعثت بها السائلة: (ح. ع. علي) من أبهـا، لها مجموعة -الحقيقة- من الأسئلة تبدأ هذه الرسالة بالسؤال الأول وتقول: من يذهب إلى مكة -يا فضيلة الشيخ­- هل عليه أن يجعل نظره للكعبة، أم إلى مكان سجوده؟","title":"المكان الذي ينظر إليه المصلي في مكة","answer":"الجواب: المشروع للمصلي أن ينظر موضع سجوده في مكة، وفي غيرها، لكن إذا أراد أن ينظر الكعبة، ينظر الكعبة في غير الصلاة، وأما في الصلاة يقبل على صلاته، ويخشع فيها، ويطرح بصره إلى موضع سجوده، هذا السنة، نعم.","link":"https://binbaz.org.sa/fatwas/11795/المكان-الذي-ينظر-اليه-المصلي-في-مكة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_518/51806.mp3","categories":["الطمأنينة والخشوع"]},{"id":13538,"question":"المستمع سرحان سالم محمد طالب من المعهد العلمي في نجران بعث يسأل ويقول: ما هي أسباب الخشوع في الصلاة؟","title":"ما هي أسباب الخشوع في الصلاة؟","answer":"الجواب: أسباب الخشوع في الصلاة: الإقبال على الله، وتذكر أنك بين يديه، وأنك في حضرته  وأنك تناجيه -جل وعلا- وأن هذه الصلاة أعظم العبادات، وأهمها بعد التوحيد، فإذا تذكرت هذه الأمور؛ خشع قلبك كما قال الله سبحانه: قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلاتِهِمْ خَاشِعُونَ [المؤمنون:1-2] ويقول ﷺ: إذا قام أحدكم يصلي فإنه يناجي ربه فلا يمس الحصى فإن الرحمة تواجهه. فالمقصود: أن الإنسان بين يدي ربه في الصلاة، فليستحضر هذا الأمر العظيم؛ حتى يخشع قلبه، وتخشع جوارحه. وفي الحديث الآخر: إذا قام أحدكم يصلي فإنه يناجي ربه؛ فلا يبصقن قبل وجهه، ولا عن يمينه، ولكن عن يساره تحت قدمه. فأنت يا عبدالله! بين يدي الله، واقف بين يديه تناجيه، وتقرأ كتابه، وتركع وتسجد بين يديه، فاخشع له سبحانه، واستحضر هذه العظمة، وأنك بين يدي الملك العظيم الذي لا أعظم منه  وهذا كله مما يسبب خشوعك وانكسارك بين يدي الله  نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11849/ما-هي-اسباب-الخشوع-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_479/47908.mp3","categories":["الطمأنينة والخشوع"]},{"id":14048,"question":"تقول أختنا: إنني في بعض الأحيان أقف لأصلي بين يدي الله، ولكنني أشعر بأنني أقرأ آية القرآن بشدة، ولا أشعر بخشوع، ولكنني أحاول ولا أستطيع، في بعض الأحيان أشعر بخشوع، وأستمر في البكاء من خشية الله، وأتذكر في الصلاة وأندم على أنني لم أخشع في المرات السابقة، هل هنا علي ذنب في هذا؟ وما هو الذنب؟ أرجو توجيهي جزاكم الله خيرا، وهل يصح الندم والتفكر أثناء الصلاة؟","title":"هل تصح الصلاة بدون خشوع؟","answer":"الجواب: الخشوع في الصلاة من أفضل القربات، ومن أسباب القبول، ومن صفات أهل الإيمان، قال تعالى في كتابه العظيم: قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلاتِهِمْ خَاشِعُونَ [المؤمنون:2]، ولكن لو عرض للإنسان شيء من التفكير، وشيء من عدم الخشوع؛ فصلاته صحيحة لا تبطل بذلك؛ لأن الإنسان عرضة للوساوس، والأفكار التي تعرض له في الصلاة؛ فلا تبطل صلاته، ولا توجب عليه الإعادة، بل صلاته صحيحة، وعليه المجاهدة لنفسه، إذا دخل في الصلاة، عليه المجاهدة، يستحضر أنه بين يدي الله، وأن الله شرع له الخشوع، فيجتهد في ذلك، ويستعين بالله على ذلك، وإذا كثر عليه الوساوس؛ استعاذ بالله من الشيطان، نفث عن يساره ثلاثًا ويقول: أعوذ بالله من الشيطان الرجيم، وهو في الصلاة لا حرج في ذلك، فقد سأل عثمان بن أبي العاص  النبي ﷺ عن ذلك، وأنه غلبت عليه الوساوس؛ فأرشده النبي ﷺ إلى أن يستعيذ بالله من الشيطان إذا عرضت له في الصلاة؛ ففعل ذلك فعافاه الله من ذلك.\nفالمقصود: أن المؤمن والمؤمنة كلاهما يجتهدان في إحضار القلب في الصلاة والخشوع، والإقبال على الصلاة، والتذكر بأن العبد بين يدي الله، وأنه يناجيه ، وأن الصلاة عمود الإسلام، وأنها أعظم الفرائض بعد الشهادتين، فإن هذا التذكر يعينه على الخشوع، وعلى حضور القلب، وعلى الإقبال على الصلاة، ولكن متى لم يحضر الخشوع، ولم يستكمل ذلك؛ فإنه لا يضره، صلاته صحيحة والحمد لله، ولا شيء عليه فيما مضى من صلوات كلها صحيحة، وإنما عليه المجاهدة، والاستعانة بالله على ذلك، وسؤاله التوفيق، والله  يقول: وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌ أُجِيبُ دَعْوَةَ الدَّاعِ إِذَا دَعَانِ فَلْيَسْتَجِيبُوا لِي وَلْيُؤْمِنُوا بِي لَعَلَّهُمْ يَرْشُدُونَ [البقرة:186]، وهو القائل سبحانه: ادْعُونِي أَسْتَجِبْ لَكُمْ [غافر:60].\nفنوصيك أيها الأخت في الله! بكثرة الضراعة إلى الله، ودعائه أن يعينك على ذكره وخشوعه في الصلاة، وأن يعيذك من نزغات الشيطان وهمزاته ووساوسه، وهكذا نوصي كل مؤمن وكل مؤمنة بالإقبال على الصلاة، وإحضار القلب فيها، والخشوع فيها، والحرص على السلامة من الوساوس، وسائر ما يقدح في الصلاة أو يضعف أجرها، والله ولي التوفيق.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12486/هل-تصح-الصلاة-بدون-خشوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_608/60806.mp3","categories":["الطمأنينة والخشوع"]},{"id":14062,"question":"تقول أختنا: إنني في بعض الأحيان أقف لأصلي بين يدي الله، ولكنني أشعر بأنني أقرأ آية القرآن بشدة، ولا أشعر بخشوع، ولكنني أحاول ولا أستطيع، في بعض الأحيان أشعر بخشوع، وأستمر في البكاء من خشية الله، وأتذكر في الصلاة وأندم على أنني لم أخشع في المرات السابقة، هل هنا علي ذنب في هذا؟ وما هو الذنب؟ أرجو توجيهي جزاكم الله خيرا، وهل يصح الندم والتفكر أثناء الصلاة؟","title":"هل تصح الصلاة بدون خشوع؟","answer":"الجواب: الخشوع في الصلاة من أفضل القربات، ومن أسباب القبول، ومن صفات أهل الإيمان، قال تعالى في كتابه العظيم: قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلاتِهِمْ خَاشِعُونَ [المؤمنون:2]، ولكن لو عرض للإنسان شيء من التفكير، وشيء من عدم الخشوع؛ فصلاته صحيحة لا تبطل بذلك؛ لأن الإنسان عرضة للوساوس، والأفكار التي تعرض له في الصلاة؛ فلا تبطل صلاته، ولا توجب عليه الإعادة، بل صلاته صحيحة، وعليه المجاهدة لنفسه، إذا دخل في الصلاة، عليه المجاهدة، يستحضر أنه بين يدي الله، وأن الله شرع له الخشوع، فيجتهد في ذلك، ويستعين بالله على ذلك، وإذا كثر عليه الوساوس؛ استعاذ بالله من الشيطان، نفث عن يساره ثلاثًا ويقول: أعوذ بالله من الشيطان الرجيم، وهو في الصلاة لا حرج في ذلك، فقد سأل عثمان بن أبي العاص  النبي ﷺ عن ذلك، وأنه غلبت عليه الوساوس؛ فأرشده النبي ﷺ إلى أن يستعيذ بالله من الشيطان إذا عرضت له في الصلاة؛ ففعل ذلك فعافاه الله من ذلك.\nفالمقصود: أن المؤمن والمؤمنة كلاهما يجتهدان في إحضار القلب في الصلاة والخشوع، والإقبال على الصلاة، والتذكر بأن العبد بين يدي الله، وأنه يناجيه ، وأن الصلاة عمود الإسلام، وأنها أعظم الفرائض بعد الشهادتين، فإن هذا التذكر يعينه على الخشوع، وعلى حضور القلب، وعلى الإقبال على الصلاة، ولكن متى لم يحضر الخشوع، ولم يستكمل ذلك؛ فإنه لا يضره، صلاته صحيحة والحمد لله، ولا شيء عليه فيما مضى من صلوات كلها صحيحة، وإنما عليه المجاهدة، والاستعانة بالله على ذلك، وسؤاله التوفيق، والله  يقول: وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌ أُجِيبُ دَعْوَةَ الدَّاعِ إِذَا دَعَانِ فَلْيَسْتَجِيبُوا لِي وَلْيُؤْمِنُوا بِي لَعَلَّهُمْ يَرْشُدُونَ [البقرة:186]، وهو القائل سبحانه: ادْعُونِي أَسْتَجِبْ لَكُمْ [غافر:60].\nفنوصيك أيها الأخت في الله! بكثرة الضراعة إلى الله، ودعائه أن يعينك على ذكره وخشوعه في الصلاة، وأن يعيذك من نزغات الشيطان وهمزاته ووساوسه، وهكذا نوصي كل مؤمن وكل مؤمنة بالإقبال على الصلاة، وإحضار القلب فيها، والخشوع فيها، والحرص على السلامة من الوساوس، وسائر ما يقدح في الصلاة أو يضعف أجرها، والله ولي التوفيق.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12486/هل-تصح-الصلاة-بدون-خشوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_608/60806.mp3","categories":["الطمأنينة والخشوع"]},{"id":15285,"question":"هذه رسالة من السائل البهتري المهدي، من المملكة المغربية، يقول: نظرًا للسرعة المفرطة التي يؤدي بها بعض الأئمة الصلاة غالبًا ما يضطر الإنسان معهم إلى عدم قراءة السورة بعد الفاتحة في الصلاة السرية، فهل أعيد الصلاة بعد مثل هؤلاء، فالصلاة معهم ينقصها الخشوع والاطمئنان؟","title":"حكم صلاة المأموم إذا لم يقرأ إلا الفاتحة لعجلة الإمام","answer":"الجواب: الواجب على الأئمة أن يتقوا الله، وأن يطمئنوا في صلاتهم في ركوعهم وسجودهم، وأن يرتلوا القراءة، ويطمئنوا في القراءة حتى يؤدوا كلام الرب بعبارة واضحة، وألفاظ واضحة، هذا الواجب على الأئمة، وأن يجتهدوا في الطمأنينة والخشوع في الصلاة حتى يستفيدوا، ويستفيد من خلفهم، وحتى يؤدوها كما شرع الله، وقد قال الله سبحانه: قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلاتِهِمْ خَاشِعُونَ [المؤمنون:1-2]. وقد أمر النبي ﷺ المسيء في صلاته أن يطمئن، قال له النبي ﷺ: إذا قمت إلى الصلاة فأسبغ الوضوء، ثم استقبل القبلة فكبر، ثم اقرأ ما تيسر لك من القرآن، ثم اركع حتى تطمئن راكعاً، ثم ارفع حتى تعتدل قائماً، ثم اسجد حتى تطمئن ساجدًا.. الحديث. فالواجب على الأئمة أن يعنوا بهذا الأمر، وأن يطمئنوا في ركوعهم وسجودهم، وبعد الركوع وبين السجدتين، وأن يعنوا بالقراءة أن يقرؤوا قراءة واضحة بينة ليس فيها خفاء ولا إسقاط شيء من الحروف، وأن يمكنوا من وراءهم من قراءة سورة بعد الفاتحة، وإن كانت غير واجبة، لكن الأفضل في السرية أن يقرأ المأموم الفاتحة، وما تيسر معها مع إمامه، والإمام كذلك يقرأ سورة مع الفاتحة، أو آيات في السرية والجهرية، لكن في السرية يقرأ المأموم زيادة على الفاتحة، وفي الجهرية لا، يكفيه الفاتحة، وينصت لإمامه في الجهرية ويكفيه الفاتحة، لكن في السرية يقرأ مع الفاتحة ما تيسر. فإذا لم يمكن المأموم أن يقرأ مع الفاتحة شيئًا؛ لأن الإمام استعجل فلا يضر ذلك؛ لأن الواجب الفاتحة، وما زاد عليها ليس بواجب، فلا يضر هذا بالصلاة ولا يبطلها، ولكن يجب أن يعتنى بالركوع والسجود من جهة الطمأنينة وبين السجدتين وبعد الركوع كذلك، هذه أمور عظيمة وفريضة لا بد فيها من الطمأنينة والاعتدال الكافي. أما القراءة فالزائد على الفاتحة ليس بواجب، وإنما هو سنة، فإن تيسر فهو الأفضل للإمام والمأموم، وإن لم يتيسر صار نقصًا لا يضر الصلاة ولا يبطلها، نعم. المقدم: جزاكم الله خير الجزاء.","link":"https://binbaz.org.sa/fatwas/13795/حكم-صلاة-الماموم-اذا-لم-يقرا-الا-الفاتحة-لعجلة-الامام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_675/nour_67511.mp3","categories":["صلاة الجماعة","الطمأنينة والخشوع"]},{"id":16041,"question":"تقول في سؤال لها: أرجو من الله تعالى أن تجدوا لي حلًا شافيًا لحالة السرحان في الصلاة ذلكم أنني أرغب أن أقبل على الله تعالى بحب وخشوع، وأترقب موعد الصلاة، وأتعوذ من الشيطان كثيرًا، إلا أنني أسرح كما ذكرت، وأتذكر مشاغل الدنيا، فماذا أفعل؟ أرجوكم إنني أتعذب كثيرًا كثيرًا.","title":"هل من علاج للسرحان في الصلاة؟","answer":"الجواب: ننصحك بالتعوذ بالله من الشيطان، إذا دخلت في الصلاة وحدث عليك هذا السرحان، يعني هذه الوسوسة، والمشاغل، فاتفلي عن يسارك ثلاث مرات، وقولي: أعوذ بالله من الشيطان الرجيم ثلاث مرات، وتسلمين، إن شاء الله. النبي ﷺ أمر بهذا بعض الصحابة، ففعله، قال: فلم يعد لي هذا الأمر يعني: نجا منه والحمد لله، فأنت عليك بقوة في التعوذ بالله من الشيطان؛ لأن هذا من الشيطان عدو الله، الشيطان عدو لك، ولغيرك من المسلمين، فعليك بالقوة إذا دخلت للصلاة كوني قوية ضد عدو الله وأقبلي على الصلاة، واحضري بقلبك في القراءة وغيرها، وإذا جد معك الوسوسة جدت معك؛ فاتفلي عن يسارك ثلاث مرات، ولو أنك في الصلاة التفتي قليلًا عن اليسار، واتفلي، وقولي: أعوذ بالله من الشيطان الرجيم، ثلاث مرات، وبهذا تسلمي -إن شاء الله- ولا يعود لك سرحان، هذا فعله عثمان بن أبي العاص الثقفي بأمر النبي ﷺ قال: فما وجدت بعد ذلك شرًا نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14673/هل-من-علاج-للسرحان-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_748/nour_74806.mp3","categories":["الطمأنينة والخشوع"]},{"id":17412,"question":"أم عبد الله لها مجموعة من الأسئلة من حائل تقول: ما حكم التسرع، أو السرعة في الصلاة مع العلم بأن الصلاة كاملة، ولا ينقص منها شيء؟","title":"الحث على الطمأنينة في الصلاة وعدم العجلة","answer":"الجواب: الواجب الطمأنينة والركود في الصلاة لقوله ﷺ للمسيء في صلاته: إذا قمت إلى الصلاة، فأسبغ الوضوء، ثم اقرأ ما تيسر لك من القرآن وفي اللفظ الآخر: ثم اقرأ بأم القرآن، وبما شاء الله، ثم اركع حتى تطمئن راكعًا، ثم ارفع حتى تعتدل قائمًا، ثم اسجد حتى تطمئن ساجدًا، ثم ارفع حتى تطمئن جالسًا، ثم اسجد حتى تطمئن ساجدًا، ثم افعل ذلك في صلاتك كلها.  ولما أخل بهذا أمره بالإعادة، لابد من الطمأنينة، فإذا كانت المصلية مطمئنة، والرجل مطمئن؛ فلا بأس، إذا اطمأن في الركوع والاعتدال بعد الركوع والسجود، وبين السجدتين، ولكن ما طول وإلا هو مطمئن فلا بأس، لكن كونه يطمئن طمأنينة واضحة جيدة في سجوده وركوعه، وبين السجدتين، وبعد الرفع يكون الطمأنينة ظاهرة، واعتدالًا ظاهر وافي يكون أكمل وأكمل، يعني: لا يتساهل في هذا؛ لأن بعض الناس قد يعتبر فعله نقرًا للصلاة، فإذا اطمأن طمأنينة تجعله غير ناقر للصلاة، طمأنينة واضحة؛ فلا بأس. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16277/الحث-على-الطمانينة-في-الصلاة-وعدم-العجلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_771/nour_77113.mp3","categories":["الطمأنينة والخشوع"]},{"id":17664,"question":"نختم هذا اللقاء سماحة الشيخ بسؤال السائل (س. ف. ر) يقول: هل تبطل الصلاة -يا سماحة الشيخ- إذا كانت بدون خشوع؟ وكيف يكون الخشوع في الصلاة؟","title":"حكم صحة الصلاة بدون الخشوع","answer":"الجواب: إذا كانت بغير طمأنينة بطلت، أما كمال الخشوع ما هو بشرط، لكن لابد من الطمأنينة في ركوعه وسجوده وبين السجدتين وبعد الركوع، فإذا اطمأن صحت، ولو كان الخشوع ما هو بكامل؛ لأن الله قال: قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلاتِهِمْ خَاشِعُونَ [المؤمنون:1-2]، كمال الخشوع من كمال الصلاة، لكن إذا اطمأن في ركوعه وسجوده وبين السجدتين وبعد الركوع؛ صحت صلاته، وإن كان لم يأت بالخشوع الكامل الكثير. نعم.","link":"https://binbaz.org.sa/fatwas/16595/حكم-صحة-الصلاة-بدون-الخشوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_594/59431.mp3","categories":["الطمأنينة والخشوع"]},{"id":17803,"question":"يقول هذا السائل يا سماحة الشيخ حفظكم الله: شخص لا يخشع في صلاته، هل الصلاة صحيحة؟ وهل هذا حديث: ليس لك من صلاتك إلا ما عقلت منها؟","title":"حكم الخشوع والطمأنينة في الصلاة","answer":"الجواب: نعم حديث، حديث صحيح، ليس للإنسان من صلاته إلا ما عقل منها فإذا كان يخشع فيها يطمئن الطمأنينة الواجبة؛ صحت، ولكن من كمال ذلك الخشوع الكامل، كما قال تعالى: قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلاتِهِمْ خَاشِعُونَ [المؤمنون:1-2]، خشوع كامل في سجوده وركوعه وبين السجدتين وبعد الركوع، والطمأنينة لابد منها، كونه يطمئن حتى يرجع كل فقار إلى مكانه، هذا لابد منه ركن، والزيادة على هذا- خشوع زائد- يكون أفضل وأكمل، أما النقر كونه ينقرها ولا يطمئن في الركوع ولا في السجود ما تصح، النبي ﷺ لما رأى أعرابيًا يصلي ولم يتم ركوعه ولا سجوده؛ أمره بالإعادة، وقال: صل فإنك لم تصل فأمره أن يعيد الصلاة، أما إذا ركد في ركوعه وسجوده وبين السجدتين وبعد الركوع، ولكنها لم يكن ذلك كثيرًا، فهذا ترك الأفضل، الأفضل أن يزيد أن يكمل، يكون خشوعه أكمل، يزيد في الطمأنينة.\nالمقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/16785/حكم-الخشوع-والطمانينة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_597/59714.mp3","categories":["الطمأنينة والخشوع"]},{"id":18452,"question":"من الجمهورية العربية اليمنية- الحديدة، هذه رسالة بعث بها أخ لنا من هناك يقول: علي أحمد سعيد ، أخونا يسأل ويقول: هل يجوز البكاء أثناء الصلاة؟","title":"حكم البكاء أثناء الصلاة","answer":"الجواب: نعم، إذا غلبه البكاء خشية لله وتعظيمًا له خشوعًا عند القراءة أو سماعها فلا بأس، قد كان النبي ﷺ يبكي وكان الأخيار يبكون، فقد ثبت عنه ﷺ أنه كان يسمع لصدره أزيز كأزيز المرجل من البكاء في الصلاة، وكان الصديق  إذا صلى بالناس لا يسمع صوته من البكاء، وكان يسمع لـعمر نشيج البكاء وهو يصلي بالناس  وأرضاه. فالمقصود أنه إذا غلبه ذلك ولم يتعمده للرياء وإنما غلبه عند سماع القرآن أو عند قراءة القرآن فإنه لا حرج عليه، ولكنه ينبغي له أن يجاهد نفسه مهما أمكن في عدم التشويش على الناس أو عدم تفهيمهم لكتاب الله ؛ لأن المقصود الخشوع مع تفهيم الناس كلام الله حتى يستمعوا له ويستفيدون كلام الله  والذي يغلبه لا يضره، والله ولي التوفيق. نعم.","link":"https://binbaz.org.sa/fatwas/17534/حكم-البكاء-اثناء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_865/nour_86502.mp3","categories":["الطمأنينة والخشوع"]},{"id":18748,"question":"هل ينقص من أجر الصلاة -سماحة الشيخ- بالنسبة للمسلم إذا أكثر الإنسان من الوساوس وسها في صلاته؟","title":"حكم الإكثار من الوساوس في الصلاة","answer":"الجواب: لا شك أن الإنسان له من صلاته ما عقل منها، أجره وثوابه على حسب ما عقل من صلاته، كلما أقبل على صلاته، وخشع فيها، وأحضر فيها قلبه؛ صار أجره أكثر، وكلما كثرت الوساوس صار الأجر أقل. فالمشروع للمؤمن أن يقبل على صلاته بقلبه، وأن يجتهد في جمع قلبه على صلاته، واستحضار ما في الصلاة من الأذكار والأدعية، وليتذكر أنه بين يدي الله، وأنه واقف بين يدي الله حتى يعظم خشوعه، وحتى يحضر قلبه، كما قال الله سبحانه: قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلاتِهِمْ خَاشِعُونَ[المؤمنون:1-2] وجاء عنه ﷺ أنه قال: إنه ليس للعبد من صلاته إلا ما عقل منها، إن العبد يقوم في الصلاة لا يكتب له منها إلا نصفها، إلا ثلثها، إلا ربعها، إلا خمسها، حتى قال: إلا عشرها. فالمقصود: أن الإنسان ينبغي له أن يقبل على صلاته، ويشرع له أن يعتني بها، ويجمع قلبه عليها حتى يكون حاضرًا بين يدي الله، يقرأ بتدبر، يركع بحضور قلب، يسجد بحضور قلب إلى أن ينهي صلاته، وقلبه حاضر خاشع، هذا هو المطلوب من المؤمن، وكلما كان الخشوع أكثر صار ثوابه، وأجره أكثر. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17871/حكم-الاكثار-من-الوساوس-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_790/nour_79004.mp3","categories":["الطمأنينة والخشوع"]},{"id":18946,"question":"يقول: وما الأسباب المعينة في الخشوع في الصلاة يا سماحة الشيخ؟","title":"الأسباب المعينة على الخشوع في الصلاة","answer":"الجواب: الإقبال على الله، وتذكر أنه واقف بين يديه، وأن الله -جل وعلا- ينظر إليه، فيتذكر عظمة الله، وأنه بين يديه، وأن الله أوجب عليه أن يطمئن في صلاته حتى يخشع. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/18138/الاسباب-المعينة-على-الخشوع-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_882/nour_88239.mp3","categories":["الطمأنينة والخشوع"]},{"id":19636,"question":"يقول السائل: هل الذي لا يخشع في صلاته كالذي لا يصلي؟ وماذا يعمل من كانت عنده وساوس من الشيطان تمنعه من الخشوع في صلاته؟ أرشدونا جزاكم الله خيرًا.","title":"وجوب الطمأنينة في الصلاة والاستعاذة من الوساوس","answer":"الجواب: الطمأنينة لابد منها، تقدم في حديث الأعرابي أن النبي ﷺ أمره بإعادة الصلاة، وقال حذيفة للذي لم يطمئن: \"إنك ما صليت ولو مت على هذا مت على غير الفطرة التي فطر عليها محمد ﷺ\". فلابد من الطمأنينة في ركوعه وسجوده، وبين السجدتين، وبعد الركوع لابد أن يطمئن ويخشع، يقول الله سبحانه: قَدْ أَفْلَحَ الْمُؤْمِنُونَ  ۝ الَّذِينَ هُمْ فِي صَلاتِهِمْ خَاشِعُونَ [المؤمنون:1-2]، لابد أن يطمئن، إذا سجد اطمأن حتى يرجع كل فقار إلى مكانه، وإذا ركع اطمأن حتى يرجع كل فقار إلى مكانه، وإذا رفع من الركوع اطمأن حتى يرجع كل فقار إلى مكانه، وإذا جلس بين السجدتين اطمأن حتى يرجع كل فقار إلى مكانه، هذا هو الواجب على المصلي. أما الوساوس فالواجب التعوذ بالله من الشيطان، إذا عرضت لك انفث عن يسارك ثلاث مرات وقل: أعوذ بالله من الشيطان الرجيم ثلاث مرات، وتزول إن شاء الله، جاهد نفسك ولا تطاوع الشيطان بالوساوس، بل احذرها وارفضها، وتعوذ بالله من الشيطان عند وجودها اتفل عن يسارك ثلاث مرات وقل: أعوذ بالله من الشيطان الرجيم ثلاث مرات، وتزول إن شاء الله. المقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/18907/وجوب-الطمانينة-في-الصلاة-والاستعاذة-من-الوساوس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_949/nour_94923.mp3","categories":["الطمأنينة والخشوع"]}]
